COLLDATA("tadabburur","ur",[[431,"§سبإ\ndeeds\nدعا كریں كہ الله تعالىٰ آپ كو كسى ایسے شخص كیلئے سفارشى بنائے جس سے آپ كو محبت ہو.\nدعا كریں كہ الله تعالىٰ آپ كےحق میں انبیاء، فرشتوں اور نیك بندوں كى سفارش قبول كرے، اور یہ چیز الله كےعلاوه اور كسى سے نہ مانگیں چاہے وه كوئى بھى ہو.\nالله تعالىٰ نے جو روزى آپ كو دى ہے اس پر اسكا شكر بجالائیں.\nguid\nدعا كریں كہ الله تعالىٰ آپ كےدل كو اپنى خشیت ، تعظیم اور محبت سے معمور كردے.\nیاد ركھیں كہ رازق صرف اللہ ہى ہے، پس رزق كسى اور سے نہ مانگیں.\nاپنى دعوت میں خیر كى خوشخبرى اور شر سے ڈرانے كو لازم پكڑیں.\nrefl\nوَلَا تَنفَعُ ٱلشَّفَٰعَةُ عِندَهُۥٓ إِلَّا لِمَنۡ أَذِنَ لَهُۥۚ\nیہ الله كى طرف سے تنبیہ اور خبر ہے كہ فرشتے گرچہ برگزیده ہیں اور انكا مقام بہت بلند ہے پھر بھى الله كى اجازت كے بغیر كسى كے حق میں سفارش نہیں كرسكتے، جب انہیں اجازت ملے گى اور اسےوه سنیں گے تو بیہوش ہوجائیں گے، جب ان كا یہ حال ہے تو بتوں كا كیا حال ہوگا؟ یا یہ كہ تم شفاعت كى امید كیسے ركھتےہو جبكہ قیامت كا تم اعتراف ہى نہیں كرتے۔ (القرطبى: ۱۷؍۳۱۱)\nاس آیت كى روشنى میں قیامت كےدن الله كےنزدیك شفاعت كى اہمیت بتلائیں.\nحَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمۡ قَالُواْ مَاذَا قَالَ رَبُّكُمۡۖ قَالُواْ ٱلۡحَقَّۖ وَهُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ ٢٣\nرسول صلی اللہ علیہ وسلم سے بہت سارى حدیثیں ثابت ہیں كہ یہ آیت فرشتوں كے بارے میں ہے، كیونكہ جب فرشتے جبریل علیہ السلام کی جانب کی جانے والی وحى سنتےہیں تو بہت ہى گھبراہٹ میں مبتلا ہوجاتےہیں ، پھر جب یہ گھبراہٹ ختم ہوتى تو بعض بعض سے كہتےہیں: تمہارے رب نے كیا كہا ؟ تو بتایا جاتا ہے كہ حق كہا ہے۔ (ابن جزى: ۲؍۲۰۵)\nاس آیت كےاندر وحى كى عظمت پر دلیل ہے ، اسے واضح كریں.\nحَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمۡ قَالُواْ مَاذَا قَالَ رَبُّكُمۡۖ قَالُواْ ٱلۡحَقَّۖ وَهُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ ٢٣\nمذكوره دونوں صفتوں كو خصوصى طور پر ذكر كرنے كى وجہ جواب كے مقام ومرتبے كى مناسبت ہے، یعنى فیصلہ حق كا ہوا ہے ہر ایك كیلئے جس كا وه مستحق ہے، كیونكہ اس پر كسى كى حالت مخفى نہیں ہے، اور اسكى طرف سے اہل حق كو حق پہونچانے میں كوئى ركاوٹ بھى نہیں بن سكتا۔ (بن عاشور: ۲۲؍۱۹۰-۱۹۱)\nآیت كریمہ كےاندر دونوں صفت (العلي الكبير) كو خصوصى طور پر ذكر كرنے كا كیا فائده ہے؟\nوَإِنَّآ أَوۡ إِيَّاكُمۡ لَعَلَىٰ هُدًى أَوۡ فِي ضَلَٰلٖ مُّبِينٖ ٢٤\nیعنى دونوں فریق میں سے ایك حق پر ہے اور دوسرا باطل پر، ایسا نہیں ہوسكتا كہ تم اور ہم بیك وقت ہدایت پر ہوں یا ضلالت پر، بلكہ ہم میں ایك ہى حق پر ہوسكتا ہے۔ (ابن كثیر: ۳؍۵۱۶)\nاس شخص كےبارےمیں آپ كى كیا رائےہے جو ادیان وفرق كے درمیان پائے جانے والے اختلافات كو بہت آسان سمجھتاہے اور گمان ركھتاہے كہ ہر كوئى حق پر ہے؟\nقُلۡ يَجۡمَعُ بَيۡنَنَا رَبُّنَا ثُمَّ يَفۡتَحُ بَيۡنَنَا بِٱلۡحَقِّ وَهُوَ ٱلۡفَتَّاحُ ٱلۡعَلِيمُ ٢٦\nصفت (الفتاح) كےبعد صفت (العليم) لایا گیا اس بات كو بتلانے كیلئے كہ اسكا فیصلہ محض عدل وانصاف پر مبنى ہوتاہے، كیونكہ وه ہر چیز كا جاننے والا ہے ، اسكے فیصلہ كرنے میں غلطى اور ظلم كے ایسے اسباب كا امكان نہیں جو جہالت ، عاجزى اور ایسى نفسیاتى كمزورى كى پیروى سے ظاہر ہوتےہیں جو حالات وانجام سے بے خبرى كى وجہ سے پیدا ہوتى ہے۔ (ابن عاشور: ۲۲؍۱۹۵)\nصفت (الفتاح) كےبعد صفت (العليم) كیوں لایا گیا؟\nوَمَآ أَرۡسَلۡنَٰكَ إِلَّا كَآفَّةٗ لِّلنَّاسِ بَشِيرٗا وَنَذِيرٗا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ٢٨\nیہ ا لله تعالىٰ كى طرف سے كھلا اعلان ہے كہ محمد صلی اللہ علیہ وسلم كو تمام عالم كى طرف مبعوث كیا ہے، اور تمام انبیاء كے برعكس محمد صلی اللہ علیہ وسلم كو تمام عالم كے لئے مبعوث كیاجانا نبی صلی اللہ علیہ وسلم کی خصوصی صفات کا حصہ ہے۔(ابن عطیہ: ۴؍۴۲۰)\nآیت میں ایك ایسى خصلت كا ذكر ہے جو محمد صلی اللہ علیہ وسلم كے ساتھ خاص ہے، وه كیا ہے؟\nوَلَوۡ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ مَوۡقُوفُونَ عِندَ رَبِّهِمۡ يَرۡجِعُ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ ٱلۡقَوۡلَ يَقُولُ ٱلَّذِينَ ٱسۡتُضۡعِفُواْ لِلَّذِينَ ٱسۡتَكۡبَرُواْ لَوۡلَآ أَنتُمۡ لَكُنَّا مُؤۡمِنِينَ ٣١\nاے محمد ! جب آپ دیكھیں گے كہ ظالموں كو ان كے رب كےپاس روك لیا گیا ہے، یعنى حساب وكتاب كى جگہ پرانہیں قید کردیاگیا ہے ،وہاں وہ آپس میں بات كرتےہوئے ایك دوسرے پر لعنت ملامت كر یں گے جب كہ وه دنیا میں ایك دوسرے كے مخلص ومددگار دوست تھے۔ اور (لَوْ) كا جواب محذوف ہے، یعنى تو آپ اس وقت بڑا ہى ہولناك معاملہ دیکھیں گے۔ (القرطبى: ۱۷؍۳۱۶)\nمشرك دوستوں كا حال بیان كریں اس وقت جب كہ وه الله كےسامنے كھڑےہوں گے.\nwords\nفُزِّعَان كے دلوں سے خوف ختم هو گيا.\nيَفتَحُوه فيصله كرتا هے.\nبِالحَقِّعدل و انصاف كے ساتھ.\nالفَتَّاحُلوگوں كے درميان فيصله كرنے والا.\nوَلاَ بِالَّذِي بَينَ يَدَيهِنه هي اس پر جو تورات زبور او رنجيل سے پهلے اترا هوا كلام هے.\nمَوقُوفُونوه مؤقف حساب ميں روكے جائيں گے.\nيَرجِعُوه ايك دوسرے پر لوٹاتے هيں."],[432,"§سبإ\ndeeds\nاللہ کی راہ میں کم از کم ایک دن کا روزہ رکھیں.\nدعا کیجئے: (اَللّٰهُمَّ اجْعَلْنَا عِنْدَ النَّعْمَاءِ مِنَ الشَّاكِرِيْنَ، وَعِنْدَ الْبَلَاءِ مِنَ الصَّابِرِيْنَ) اے اللہ تو ہمیں نعمتوں میں شکرکرنے والا اور مصیبتوں میں صبر کرنے والا بنادے.\nاپنے مال سے كسى دعوتى پروگرام میں خرچ كریں اس امید میں كہ الله اسكا بدلہ دےگا.\nguid\nباطل میں بزرگوں كى بات ماننے سے بچیں.\nمنافقوں كى دوستى سے بچیں جو اپنى مكارى سے مختلف حیلوں كے ذریعے الله كى اطاعت سے روكتےہیں.\nیاد ركھیں كہ كافر اور گنہگار اس وقت سخت ندامت كا سامنا كریں گے جب اپنى آنكھوں سے عذاب کا مشاہده كریں گے.\nrefl\nقَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ لِلَّذِينَ ٱسۡتُضۡعِفُوٓاْ أَنَحۡنُ صَدَدۡنَٰكُمۡ عَنِ ٱلۡهُدَىٰ بَعۡدَ إِذۡ جَآءَكُمۖ بَلۡ كُنتُم مُّجۡرِمِينَ ٣٢\nیعنى ہم نے جو كیا وه زیاده سے زیاده یہى تھا كہ ہم نے تمہیں بلایا اور تم نے ہمارى بات بلا دلیل مان لى، جبكہ تم نےرسولوں كى لائى ہوئى واضح دلیلوں اور حجتوں كى مخالفت كى ، یہ سب تم نے اپنى شہوتوں اور اپنے اختیارات سے كیا، اسى لئے انہوں نے ان كےبارےمیں كہا: (بل كنتم مجرمين) (بلكہ تم ہى مجرم تھے) ۔(ابن كثیر: ۳؍۵۱۸)\nكمزور پیروكاروں كو مجرمین كیوں كہا گیا؟\nوَقَالَ ٱلَّذِينَ ٱسۡتُضۡعِفُواْ لِلَّذِينَ ٱسۡتَكۡبَرُواْ بَلۡ مَكۡرُ ٱلَّيۡلِ وَٱلنَّهَارِ إِذۡ تَأۡمُرُونَنَآ أَن نَّكۡفُرَ بِٱللَّهِ وَنَجۡعَلَ لَهُۥٓ أَندَادٗاۚ\nمطلب یہ ہے كہ كمزور پیروكار متكبر سرداروں سے كہیں گے: بلكہ شب وروز ہمارے ساتھ تمہارى مكارى ہمارے كفر كا سبب تھی۔ (ابن جزى: ۲؍۲۰۷)\nہر وه دوستى اور تابعدارى جس كى بنیاد غیر شرعى ہو وه عداوت میں بدل جائےگى، آیت كى روشنى میں اسكى مثال بیان كریں.\nوَقَالَ ٱلَّذِينَ ٱسۡتُضۡعِفُواْ لِلَّذِينَ ٱسۡتَكۡبَرُواْ بَلۡ مَكۡرُ ٱلَّيۡلِ وَٱلنَّهَارِ إِذۡ تَأۡمُرُونَنَآ أَن نَّكۡفُرَ بِٱللَّهِ وَنَجۡعَلَ لَهُۥٓ أَندَادٗاۚ\nیہ پیروكاروں كى طرف سے سرداروں سے بحث ومباحثہ ہوگا جس وقت وه ان سے كہیں گے كہ تم نے اپنے اختیارات سے كفر كیا، تو كمزور پیروكار كہیں گے:بلكہ شب وروز ہمارے ساتھ تمہارى مكارى ہمارے كفر كا سبب تھی۔ اور مكر کی شب وروز كى طرف اضافت کی گئی تاكہ یہ اضافت دوام اور ہمیشگى پر دلالت كرے۔ (ابن عطیہ:۴؍۴۲۱)\nقیامت كےدن كمزور پیروكار اپنے گمراه كرنے والے سرداروں كو كیا جواب دیں گے؟\nوَأَسَرُّواْ ٱلنَّدَامَةَ لَمَّا رَأَوُاْ ٱلۡعَذَابَۚ\nیعنى اس حجت كا تاروپود بكھر جائےكا جس كے ذریعے سے وه ایك دوسرےپر حجت قائم كرتےتھے كہ وه عذاب سے بچ جائیں گے، اور وه جان لیں گے كہ وه ظالم ہیں اور عذاب كے مستحق ہیں۔ ان میں سے ہر مجرم بے حد پشیمان ہوگا اور وه تمنا كرےگا كہ كاش وه حق پر ہوتا اور اس نے باطل كو چھوڑ دیا ہوتا جس نے اسے اس عذاب میں مبتلا كیا ہے۔ اپنے جرائم كا اقرار دل میں کریں گے، کیونکہ زبانی اقرار سے انہیں فضیحت لاحق ہونے کا خوف ہوگا۔ (السعدى: ۶۸۱)\nقیامت كےدن كافر پشیمانى كا اظہار كیوں نہیں كریں گے؟\nوَقَالُواْ نَحۡنُ أَكۡثَرُ أَمۡوَٰلٗا وَأَوۡلَٰدٗا وَمَا نَحۡنُ بِمُعَذَّبِينَ ٣٥\nیعنى ان لوگوں نے مال واولاد پر فخر كیا اور یہ سمجھ بیٹھے كہ یہ ان سے الله كى محبت اور اس كے اہتمام كى دلیل ہے، اور ایسا نہیں ہوسكتا كہ الله انہیں دنیا میں تو نوازے اور آخرت میں عذاب دے۔ (ابن كثیر: ۳؍۵۱۹)\nكافروں نے مال واولاد كى كثرت اور عذاب نہیں دینے كے مابین تعلق كیوں بنایا؟\nقُلۡ إِنَّ رَبِّي يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ٣٦\nیہ خبر ہے جس میں ان پر اس بات كى تردید ہے كہ دنیا كےاندر روزى کوگھٹانا بڑھانا الله كى مشیئت پر منحصر ہے، چنانچہ الله چاہے تو ایك كافر اور گنہگار پر روزى كو كشاده كردےاور مومن اور فرمانبردار بندے پر تنگ كردے، اور اسكے برعكس بھى كرسكتاہے، چنانچہ اس میں كسى طور بھى آخرت كے معاملے میں كوئى دلیل نہیں ہے۔ (ابن جزى: ۲؍۲۰۸)\nتقسیم رزق میں الله كى كیا سنت ہے؟ اور كیا یہ آخرت میں نجات كیلئے معیار حقیقى ہوسكتا ہے؟\nوَمَآ أَنفَقۡتُم مِّن شَيۡءٖ فَهُوَ يُخۡلِفُهُۥۖ وَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ ٣٩\nابن العربى نے كہا: ممكن ہے جتنا خرچ كیا ہو اتنا ہى بدلہ ملے ، یا زیاده بھى مل سكتا ہے، اور كبھى اسكا اجر دنیا میں بھى مل سكتا ہے، اور كبھى اسےآخرت میں ذخیره بھى كیا جاسكتاہے، اور یہ مقبول دعا كى طرح سےہے۔ میں كہتاہوں: كبھى صحت وتندرستى كى شكل میں بھى بدلہ دیا جاسكتا ہے، اور كبھى تعمیر كى شكل میں بھى، اور الله کے اسكى مخلوق میں بہت سارے اسرار ہیں۔ (ابن عاشور: ۲۲؍۲۲۱)\nان قسموں كو ذكركریں جو الله تعالىٰ اپنے بندے كو بدلے كے طور پر عطا كر تا ہے جب وه خرچ كرتاہے؟\nwords\nالنَّدَامَةَتحسر/حسرت / ندامت.\nيَبسُطُوه وسعت ديتا هے.\nزُلفَىقربت.\nالغُرُفَاتجنت ميں بلند مقامات.\nمُعَاجِزِينَوه گمان كرتے هيں هم سے بھاگ جائيں گے.\nمُحضَرُونَزبانيه فرشتے انهيں جهنم ميں حاضر كريں گے.\nوَيَقدِرُ لَهُاس پر تنگي كرديتا هے."],[433,"§سبإ\ndeeds\nكلمۂ توحید كى گواہى دیں اس مقصد سے كہ الله سبحانہ وتعالىٰ كےسوا ہر معبود سے براءت كا اظہار ہوسكے.\nاپنے گھرو الوں یا ساتھیوں كےپاس ایك پیغام بھیجیں جس میں جادو سے اور جادوگروں كےپاس جانے سے انہیں ڈرائیں، اس بات كى وضاحت كرتےہوئے كہ یہ الله كى عبادت كےمنافى ہے.\nخود كو كچھ وقت كیلئے فارغ كیجئے اور قرآن كى كوئى سورت پڑھئے.\nguid\nمقرب فرشتوں كى اقتداء میں آپ بھى الله كى پاكى اور عظمت بیان كریں ، اسكى تسبیح كریں اور خاص طور سے اس وقت جب اس كے تعلق سےکوئی ایسى بات سنیں جس سے اسكى عظمت وجلال میں تنقیص ہورہى ہو.\nاپنے دل میں فكرى عبادت كو زنده كریں كہ یہ قلبى عبادات میں سب سے برتر ہے.\nدین كو فانى دنیا كے حصول كیلئے زینہ مت بنائیں؛ كیونكہ آخرت ہى بہتر اور باقى رہنےوالى ہے.\nrefl\nوَيَوۡمَ يَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ يَقُولُ لِلۡمَلَٰٓئِكَةِ أَهَٰٓؤُلَآءِ إِيَّاكُمۡ كَانُواْ يَعۡبُدُونَ ٤٠\nالله تعالىٰ خبر دےرہا ہے كہ قیامت كےدن پورى مخلوق كے سامنے مشركوں كو رسوا كرے گا اور فرشتوں سے پوچھے گا: (أهؤلاء إياكم كانوا يعبدون) كیا یہى لوگ ہیں جو تمہارى عبادت كرتےتھے؟ ) (ابن كثیر: ۳؍۵۲۰)\nقیامت كے دن الله تعالىٰ فرشتوں سے مشركین كى ان كى عبادت كے تعلق سے پوچھے گا، اسكى كیا حكمت ہے؟\nوَيَوۡمَ يَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ يَقُولُ لِلۡمَلَٰٓئِكَةِ أَهَٰٓؤُلَآءِ إِيَّاكُمۡ كَانُواْ يَعۡبُدُونَ ٤٠\nصرف فرشتوں سے اقرار كروانے اور مشركین كے خلاف ان كى گواہى لینے كى وجہ یہ ہے كہ فرشتوں كى الوہیت كو باطل كردینے سے ان سے چھوٹى مخلوق كى الوہیت بدرجہ اولیٰ خود بخود باطل ہوجاتى ہےجن کی اللہ کے سوا عبادت کی جاتی ہے، اور حشر كے اسباب میں سے یہ اقرار بھى ایك اہم سبب ہے۔ (ابن عاشور ہے: ۲۲؍۲۲۲)\nصرف فرشتوں سے اقرار كروانے اور مشركین كے خلاف ان كى گواہى لینے كى كیا وجہ ہے؟\nوَكَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَمَا بَلَغُواْ مِعۡشَارَ مَآ ءَاتَيۡنَٰهُمۡ فَكَذَّبُواْ رُسُلِيۖ فَكَيۡفَ كَانَ نَكِيرِ ٤٥\nیعنى پچھلى امتوں كو ہم نے طاقت وقوت ، نعمت اور درازئ عمر عطا كى (فكذبوا رسلي فكيف كان نكير) (تو انہوں نے میرے رسولوں كو جھٹلا دیا، تو دیكھا میرا بدلنا كیسا ہوا) یعنى انكے خلاف میرا بدل جانا، ایسا كہہ كر الله تعالىٰ پچھلى امتوں كے عذاب سے اس امت كےكفار كو ڈرا رہاہے۔(البغوى: ۳؍۶۱۱)\nامت محمدیہ سے پہلى جھٹلانے والى طاقتور قوموں كى طرف قرآن نے اشاره كیا ہے، اس میں كیا راز ہے؟\nوَكَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَمَا بَلَغُواْ مِعۡشَارَ مَآ ءَاتَيۡنَٰهُمۡ فَكَذَّبُواْ رُسُلِيۖ فَكَيۡفَ كَانَ نَكِيرِ ٤٥\nمفہوم یہ ہے كہ محمد صلی اللہ علیہ وسلم كے معاملے میں غور وفكر كرنے كیلئے الله كےواسطے كھڑےہوجاؤ، اس طرح سے كہ اس میں کسی نفسانی خواہش كا دخل نہ ہو اور نہ ہى كسى جانب میلان ہو، یہاں كھڑا ہونے سے مراد دونوں پیر پر كھڑا ہونا نہیں ہے، بلكہ حكم كو بجا لانا اور اسكے لئے كوشش كرنا ہے۔(ابن جزى: ۲؍۲۰۹)\nالله كے حكم كیلئے كھڑا ہونا خالص كب ہوگا؟ اور كب باطل ہوگا؟\n۞قُلۡ إِنَّمَآ أَعِظُكُم بِوَٰحِدَةٍۖ أَن تَقُومُواْ لِلَّهِ مَثۡنَىٰ وَفُرَٰدَىٰ ثُمَّ تَتَفَكَّرُواْۚ مَا بِصَاحِبِكُم مِّن جِنَّةٍۚ إِنۡ هُوَ إِلَّا نَذِيرٞ لَّكُم بَيۡنَ يَدَيۡ عَذَابٖ شَدِيدٖ ٤٦\n(ثم تتفكروا) پھر غور كرو كہ كیا تم نے كبھى اپنے ساتھى كے تعلق سے جھوٹ كا تجربہ كیا ہے، یا اس كے اندر كبھى جنون دیكھا ہے، یا اسكى حالت میں كبھى كسى طرح كا بگاڑ پایا، یا كبھى كسى جادو كے دعویدار كےپاس گیا، یا كبھى قصے كہانیاں سیكھا اور كتابیں پڑھیں، یا كبھى تم نے ایسا سمجھا كہ اسے تمہارے مال كى لالچ ہو، یا كبھى تم كسى ایك بھى سورت میں اس سے مقابلہ كرنے پر قادر ہوئے ؟ جب اس طرح غور وفكر كركے اس كى سچائى كا علم تمہیں ہوگیا تو پھر كیا وجہ ہے اس ہٹ دھرمى كى؟ (القرطبى: ۱۷؍۳۳۰)\nكس طرح كے غور وفكر كى دعوت انہیں دى گئى ہے؟ اور اس سے ہم باطل سے حق كو كیسے جانیں گے؟\nقُلۡ مَا سَأَلۡتُكُم مِّنۡ أَجۡرٖ فَهُوَ لَكُمۡۖ\nایك اور مانع ہوسکتا ہے جو نفوس كو داعئ حق كى آواز پر لبیك كہنے سے روكتا ہے اوروه مانع یہ ہوسکتاہے كہ داعى اپنى آواز پر لبیك كہنے والوں سے ، اپنى دعوت كى اجرت كے طور پر مال اینٹھ لیتا ہو ، اس لئے الله تبارك وتعالىٰ نے اس قسم كے ہتھكنڈوں سے اپنے رسول كى براءت بیان كرتےہوئے فرمایا: (قل ما سألتكم من أجر) فرما دیجیئے: میں تم سے كوئى اجر نہیں مانگتا۔ یعنى تمہارے حق كى اتباع كرنےپر۔(فَهُوَ لكم)یعنی میں تمہیں گواہ بناتا ہوں کہ بالفرض اگر یہ اجرت ہے بھی تو تمہارے فائدے کے لئے ہے۔(السعدى: ۶۸۳)\nاس آیت میں الله تعالىٰ نے سچے دعاة كى نشانیوں میں سے ایك نشانى كا ذكر كیا ہے، وه كیا ہے؟\nقُلۡ إِنَّ رَبِّي يَقۡذِفُ بِٱلۡحَقِّ عَلَّٰمُ ٱلۡغُيُوبِ ٤٨\nدیگر الہى اوصاف میں سے خصوصى طور سے (علاَّم الغيوب) كو ذكر كرنے سے اس بات كى طرف اشاره ہے كہ نیتوں كو جاننے والا وہى ہے، اور یہ چیز كہنے والا بھى جانتا ہے، چنانچہ جسے یہ پتہ ہو وہ الله پر یہ باطل دعویٰ کرنے کی جراءت نہیں کرسکتا کہ اللہ نے اسے تمہاری طرف بھیجا ہے۔ (یعنی وہ اس دعویٰ میں سچا ہے) (ابن عاشور: ۲۲؍۲۳۸)\nآیت كریمہ میں (علاَّم الغيوب) جیسى صفت لانے كا كیا فائده ہے؟\nwords\nيَدرُسُونَهَاوه اس كو پڑھتے هيں.\nنَكِيرِميرا ان كا انكار كرنا.\nبِوَاحِدَةٍكوئي ايك خصلت.\nمَثنَىدو دو.\nجِنَّةٍجنون.\nيَقذِفُ بِالحَقِّوه حق دلائل سے باطل كا رد كرتا هے؛ اسے مٹا كر ركھ ديتاهے."],[434,"§سبإ ، فاطر\ndeeds\nدعا کیجئے: “اَللّٰهُمَّ اجْعَلِ الْقُرْاٰنَ الْعَظِيْمَ رَبِيْعَ قَلْبِىْ،وَنُوْرَ صَدْرِیْ وَجَلَاءَ حُزْنِي وَذَهَابَ هَمِّيْ”اےا للہ! قرآن کو میرے دل کی بہار، سینے کا نور، میرے غم کو دورکرنے والا اور میری فکرختم کرنے والا بنادے.\nكوئى ایسا حرام كلمہ یاد كریں جسے كبھى اپنى زبان سے نكالا ہو ، پھر الله سے استغفار كریں.\nقرآنى آیات كى روشنى میں فرشتوں كے صفات میں سے پانچ صفتوں كو اكٹھا كریں.\nguid\nالله سبحانہ وتعالىٰ كے دونوں صفات: (اَلسَّمِيْع) اور (اَلْقَرِيْب) كے بارےمیں آپ كا جاننا آپكو اس احساس كى طرف دعوت دیتاہے كہ الله تعالىٰ آپ كےقریب ہے اور آپ كى دعائیں قبول كرتاہے.\nابھى سے الله كى اطاعت پر جم جائیں اور عبادات كو لازم پكڑ لیں قبل اس كے كہ آپ اسكى خواہش كریں اور وه پورى نہ ہوں.\nالله كى عظیم مخلوق فرشتوں كےبارےمیں غور وفكر كریں كہ اس قدر عظیم ہونے كےباوجود وه كس قدر الله كےسامنے خشوع وخضوع اور انكسارى كے ساتھ رہتےہیں.\nrefl\nوَلَوۡ تَرَىٰٓ إِذۡ فَزِعُواْ فَلَا فَوۡتَ وَأُخِذُواْ مِن مَّكَانٖ قَرِيبٖ ٥١\n(ولو ترى إذ فزعوا) اور اگر آپ دیكھیں گے كہ وه گھبراہٹ میں مبتلا ہوں گے، یعنى دنیا كےاندر موت آنے كے وقت ، یا ان پر الله كى طرف سے كسى دوسرے عذاب كےآنے كےوقت۔ اور كہاگیا: یہاں مراد صور پھونكنے سے ان كا قبروں میں گھبرانا مراد ہے۔(القرطبى: ۱۷؍۳۳۳)\nكافر كا اس وقت كیا حال ہوگا جب وه خوفناك حقائق كا سامنا كرےگا؟\nوَيَقۡذِفُونَ بِٱلۡغَيۡبِ مِن مَّكَانِۢ بَعِيدٖ ٥٣\nاپنے باطل اندازوں كےذریعے سے تاكہ اس طرح وه حق كو سرنگوں كریں، مگر وه ایسا كرنے میں كامیاب نہیں ہوں گے جس طرح بہت دور سے تیراندازى كرنے والے كا تیر صحیح نشانے پر نہیں پڑسكتااسى طرح یہ بہت محال ہے كہ باطل حق كو مغلوب كرسكے یا اس كو روك سكے۔ حق كى غفلت كےوقت باطل یکبارگی حملہ آور ہوتا ہے مگر جب حق سامنے آكر باطل كا مقابلہ كرتا ہے تو وه اس كا قلع قمع كردیتاہے۔(السعدى: ۶۸۴)\nاہل باطل كا حق پرنشانہ لگانے كو دور جگہ سے تعبیر كیوں كیا گیا ہے؟\nوَحِيلَ بَيۡنَهُمۡ وَبَيۡنَ مَا يَشۡتَهُونَ كَمَا فُعِلَ بِأَشۡيَاعِهِم مِّن قَبۡلُۚ إِنَّهُمۡ كَانُواْ فِي شَكّٖ مُّرِيبِۢ ٥٤\nیعنى انہیں جنت میں داخل ہونے سے روك دیا جائےگا، اور كہا گیاہے: انہیں اس وقت ایمان سے فائده اٹھانے سے روك دیا جائےگا، اور كہاگیاہے: انہیں دنیا میں واپس جاكر اس كى نعمتوں سے فائده اٹھانے سے روك دیا جائےگا۔ (ابن جزى: ۲؍۲۱۰)\nكفار كس چیز كى خواہش كریں گے جس سے انہیں روك دیاجائےگا؟\nوَحِيلَ بَيۡنَهُمۡ وَبَيۡنَ مَا يَشۡتَهُونَ كَمَا فُعِلَ بِأَشۡيَاعِهِم مِّن قَبۡلُۚ إِنَّهُمۡ كَانُواْ فِي شَكّٖ مُّرِيبِۢ ٥٤\nاس تشبیہ كا فائده یہ ہے كہ مشركین مكہ میں سے جو لوگ زنده ہیں انہیں پچھلى امتوں كا عذاب یاد دلایا جائے ، تاكہ انہیں یقین ہوجائے كہ الله كى سنت ایك ہى ہے، اور یہ كہ ان كے وه بت جنہیں ان لوگوں نے الله كے نزدیك سفارشى سمجھ ركھا ہے وه انہیں كچھ بھى فائده نہیں پہونچا سكتے۔(ابن عاشور: ۲۲؍۲۴۵)\nآیت كریمہ كےاندر تشبیہ كا كیا فائده ہے؟\nٱلۡحَمۡدُ لِلَّهِ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ جَاعِلِ ٱلۡمَلَٰٓئِكَةِ رُسُلًا أُوْلِيٓ أَجۡنِحَةٖ مَّثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۚ يَزِيدُ فِي ٱلۡخَلۡقِ مَا يَشَآءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ١\n(الحمد لله) سے اس سورت كو شروع كرنا اس بات كى طرف اشاره ہے كہ اس كے اندر الله کی عظمت پر مبنی صفات كا ذكر ہوگا، اور فعلى صفات میں سے الله كیلئے ارض وسماء كى پیدائش كى صفت لانا اور یہ كہ ارض وسما میں سب سے بہتر مخلوق فرشتوں اور رسولوں كى ہے، اس بات كى طرف اشاره ہے كہ یہ سورت توحید اور رسولوں كى تصدیق كیلئے نازل ہوئى ہے۔ (ابن عاشور: ۲۲؍۲۴۸)\nسورۂ فاطر (الحمد لله) سے شروع كیوں كى گئى؟\nمَّا يَفۡتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحۡمَةٖ فَلَا مُمۡسِكَ لَهَاۖ وَمَا يُمۡسِكۡ فَلَا مُرۡسِلَ لَهُۥ مِنۢ بَعۡدِهِۦۚ\n(ما يفتح الله للناس من رحمة) كہاگیا: یہاں رحمت سے مراد بارش اور رزق ہے۔(فلا ممسك لها) یعنى اسے كوئى روك نہیں سكتا۔ (وما يمسك فلا مرسل له من بعده) اور جو روك دے تو اسے كوئى چھوڑنے والا نہیں ، پس وه (العزيز) یعنى ہر چیز پر غالب ہے، ان تمام چیزوں میں جنہیں وه روك لے، اور (الحكيم) یعنى حكمت والا ہے ان تمام چیزوں میں جنہیں وه چھوڑ دے۔ (البغوى: ۳؍۶۱۶)\nكیا مخلوق میں سے كوئى كسى ایسى چیز كو روك سكتا ہے جسے الله نے آپ كیلئے مقدر كرركھا ہو؟\nيَٰٓأَيُّهَا ٱلنَّاسُ ٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡۚ هَلۡ مِنۡ خَٰلِقٍ غَيۡرُ ٱللَّهِ يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ ٣\nالله تعالىٰ اپنے بندوں كو تنبیہ اور رہنمائى كررہا ہے كہ اسكى تنہا عبادت كرنے میں اسكى وحدانیت پر استدلال كریں، كہ جیسے پیدا كرنے اور روزى دینے میں وه تنہا ہے اسى طرح عبادت میں بھى وه تنہا ہے، اس لئے اسى كى عبادت كریں اور اسكے ساتھ كسى صنم ، بت یا قبر و شجر وغیره كو شریك نہ كریں۔ (ابن كثیر: ۳؍۵۲۵)\nپیدائش اور رزق كا توحید عبادت كےساتھ كیا تعلق ہے؟\nwords\nفَزِعُواوه عذاب ديكھ كر گھبرا گئے.\nفَلاَ فَوتَپس كوئي نجات نهيں؛ نه جائے فرار.\nوَأَنَّى لَهُمُ التَّنَاوُشُاب وه كيسے ايمان پاسكتے هيں جب كه وه آخرت ميں هيں.\nوَيَقذِفُونَ بِالغَيبِوه جھوٹے گمان چلاتے هيں.\nبِأَشيَاعِهِمان كے امثال سابقه امتوں كے كافر.\nفَأَنَّى تُؤفَكُونَكيسے تم اس كي توحيد سے منه موڑتے هو."],[435,"§فاطر\ndeeds\nپڑھئے: “اَللّٰهُمَّ لَاتَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّىْ، وَلَا مَبْلَغَ عِلْمِىْ، وَلَا إ٘لَى النَّارِ مَصِيْرِیْ” اے اللہ! دنیا کو میری سب سے بڑی فکر اور میرے علم کی انتہا نہ بنانا اور نہ جہنم کو میرا ٹھکانہ بنانا.\nآپ كےساتھ شیطان كى جو عداوت ہے اسے صبح وشام یاد كریں، اور اس سے الله كى پناه مانگیں اور ہمیشہ اس سے محتاط رہیں.\nالله كى خوشنودى كى خاطرراستے سے تكلیف ده چیز كو ہٹا دیں یا اپنى محنت یا مال سے كسى محتاج كى مدد كردیں.\nguid\nایك داعى كیلئے اس بات میں تسلى ہے كہ پہلے كے رسولوں سے بھى اعراض كیا گیا اور انہیں جھٹلایاگیا.\nجس نے شیطان كى عداوت كو محسوس كیا وه محتاط رہا.\nسنت اور صحیح دلیل كو لازم پكڑیں،بدعت اور خواہشات نفس كى پیروى سے بچیں تاكہ ان میں سے نہ ہوجائیں جن كے عمل كو شیطان مزین كركے پیش كردیتا ہے تو وه اسے اچھا سمجھنے لگتاہے.\nrefl\nيَٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعۡدَ ٱللَّهِ حَقّ\nجب اس كا وعده سچا ہے تو اسكے لئے تیارى كرو اپنے اچھے اوقات میں نیك اعمال كى طرف سبقت كرو اور كوئى راہزن تمہارى راه كو كھوٹى نہ كرنے پائے۔ (السعدى: ۶۸۵)\nجب آپ كو یہ معلوم ہوجائے كہ الله كا وعده حق ہے تو آپ كو كیا كرنا چاہئے؟\nيَٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ ٥\nسعید بن جبیر نے كہا: دنیا كا دھوكہ یہ ہے كہ انسان اسكى نعمتوں اور لذتوں میں پڑ كر آخرت كیلئے عمل سے غافل ہوجائے، اور كہے: ﴿يَٰلَيۡتَنِي قَدَّمۡتُ لِحَيَاتِي﴾ [الفجر:۲۴] (كاش میں نے اپنى زندگى كیلئے كچھ كیا ہوتا) (القرطبى: ۱۷؍۳۴۶)\nدنیا كا دھوكہ كیسے ہوتاہے؟\nيَٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ ٥\nآیت میں دو دھوكےكا ذكر ہے: ایك تو آدمى خود اپنى ذات سے دھوكہ كھاتاہے، اور وه خود ا س دنیا كى رونق اور زرق برق چیزوں كو اپنے لئے مزین كرتا ہے اسے بہتر سمجھ كر، جبكہ ا س كے انجام سے بے خبر ہوتاہے، كہ بظاہر كس طرح اسكا نقصان پوشیده ہے، او ر وه یہ نہیں سمجھتا كہ یہ شیطان كى طرف سے ہے۔ اور دوسرا دھوكا شیطان كى طرف سے كھاتاہے، اور یہی معاملہ اس دنیا میں پائے جانے والے تمام دھوکوں کا ہے ، بعض پر انسان خود غالب آجاتا ہے اور بعض دھوكہ انسانوں اور جنوں كے شیاطین سے كھاتاہے۔ (ابن عاشور: ۲۲؍۲۵۹)\nآیت كےاندر دو دھوكوں سے ڈرایا گیا ہے ، وه كیا ہیں؟\nإِنَّ ٱلشَّيۡطَٰنَ لَكُمۡ عَدُوّٞ فَٱتَّخِذُوهُ عَدُوًّاۚ إِنَّمَا يَدۡعُواْ حِزۡبَهُۥ لِيَكُونُواْ مِنۡ أَصۡحَٰبِ ٱلسَّعِيرِ ٦\nشیطان كى عداوت جب فطرى ٹھہرى جس كا خاتمہ ناممكن ہے حتیٰ کہ اس شخص سے بھی جو اسے معاف کردے اسى لئے الله نے اس سے دشمنى ركھنے كا حكم دیا ؛ كیونكہ انسان اگر اسے اپنا دشمن نہیں بنائےگا تو اسكے مكر وسازش اور دھوكے سے بھى محفوظ نہیں ره سكے گا ، اور اس كى دشمنى كے لوازم میں سے یہ بھى ہے كہ انسان اس كے برخلاف عمل كرے جس كى طرف وه اسے بلائے تاكہ اسكے چال سے بچ سكے، اور اس لئے بھى كہ وه عمل صالح كو كبھى پسند نہیں كرتا۔ (ابن عاشور: ۲۲؍۲۶۱)\nالله تعالىٰ نے شیطان كو مطلق طور پر دشمن ركھنے كا حكم كیوں دیا؟ معاف كرنے كا حكم كیوں نہیں دیا؟\nإِنَّ ٱلشَّيۡطَٰنَ لَكُمۡ عَدُوّٞ فَٱتَّخِذُوهُ عَدُوًّاۚ إِنَّمَا يَدۡعُواْ حِزۡبَهُۥ لِيَكُونُواْ مِنۡ أَصۡحَٰبِ ٱلسَّعِيرِ ٦\nیعنى الله كى اطاعت كركے اس سے دشمنى كرو، اور اسكى بات نہ مانو- فضیل بن عیاض رحمہ اللہ كہتےتھے: اے جھوٹے، اے بہتان باز ! الله سےڈر، اور شیطان كو كھلے عام گالى مت دے، جبكہ تم خلوت میں اسكے دوست رہتےہو۔ اور ابن سماك رحمہ اللہ نےكہا: تعجب ہے اس شخص پر كہ محسن عظیم كےاحسان كو جاننے كے بعد بھى اسكى نافرمانى كرتاہے اور کمینے كى دشمنى كو جاننے كےبعد بھى اسكى فرمانبردارى كرتاہے۔(البغوی:۳؍۶۱۶، القرطبى: ۱۷؍۳۴۷)\nبحكم الٰہى آپ كیسے الله كےدشمن ابلیس سے دشمنى كریں گے؟\nمَن كَانَ يُرِيدُ ٱلۡعِزَّةَ فَلِلَّهِ ٱلۡعِزَّةُ جَمِيعًاۚ\nیعنى اے عزت كے طلبگار! عزت اس سے طلب كر جس كےہاتھ میں عزت ہے، اور تمام عزت الله كےہاتھ میں ہے، اور یہ عزت اسكى اطاعت كركے ہى مل سكتى ہے۔(السعدى: ۶۸۵)\nمسلمان كو كیا فائده ملتا ہے یہ جان كر كہ سارى عزت الله كے ہاتھ میں ہے؟\nمَن كَانَ يُرِيدُ ٱلۡعِزَّةَ فَلِلَّهِ ٱلۡعِزَّةُ جَمِيعًاۚ\nآیت كےاندر تین معانى كا احتمال ہے: (۱) اور یہى سب سے راجح ہے، جو عزت حاصل كرنا چاہتا ہو وه الله كےپاس طلب كرے، كیونكہ سارى عزت الله كے پاس ہے۔ (۲) جو عزت چاہتا ہو اسلام كو غلبہ دیكر تو جان لے كہ سارى عزت الله كےلئےہے، پس اسلام پر غلبہ حاصل کرنے والامغلوب ہے۔ (۳) جو جاننا چاہتا ہو كہ عزت كس كیلئے ہے تو جان لے كہ سارى عزت الله كیلئے ہے۔ (ابن جزى: ۲؍۲۱۲)\nالله تعالىٰ نےعزت كے طلبگار كیلئے راستہ بتلایا ہے ، اسے واضح كریں.\nwords\nفَلاَ تَغُرَّنَّكُمُوه تمهيں دھوكه نه دے؛ تمهيں غافل نه كردے.\nالغَرُورُشيطان.\nفَلاَ تَذهَباپني جان كو هلاك نه كريں.\nحَسَرَاتٍان گمراهوں كے كفر پر غمگين.\nفَتُثِيرُآپ حركت ديں.\nيَبُورُوه اس كو خراب كرتا هے؛ ختم كرديتا هے.\nمُعَمَّرٍلمبي عمر والا."],[436,"§فاطر\ndeeds\nدعا کیجئے: “اَللّٰهُمَّ اٰتِ نَفْسِىْ تَقْوَاهَا، وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا، أَنْتَ وَلِيُّهَا وَمَوْلَاهَا”اے اللہ! تومیرے نفس کو تقویٰ عطافرما، اور اسے پاک و صاف کردے، تو بہترین پاک و صاف کرنے والا ہے، توہی میرے نفس کا ولی و مولیٰ ہے.\nقلبى اعمال اور انكى اہمیت پر كوئى كتاب پڑھیں.\nاپنے مال میں سے كچھ صدقہ كریں، یا ا س رات جاگ كر نماز پڑھیں یا قرآن كى تلاوت كریں.\nguid\nغیر الله كو پكارنے سے بچیں.\nالله سبحانہ وتعالىٰ خاكسار دلوں كے زیاده قریب ہے.\nنصیحت پكڑنے كى فكر كریں، اور وعظ ونصیحت سے استفاده كریں آپ الله كے ڈرنے والے بندوں میں ہوجائیں گے.\nrefl\nوَٱلَّذِينَ تَدۡعُونَ مِن دُونِهِۦ مَا يَمۡلِكُونَ مِن قِطۡمِيرٍ ١٣\nیعنى وه قلیل یا كثیر كسى چیز كے مالك نہیں حتى كہ وه اس معمولى چھلكے كےبھى مالك نہیں جو كھجور كى گٹھلى كے اوپر ہوتا ہے جو حقیر ترین چیز ہے۔ پھر ان خودساختہ معبودوں كو كیسے پكارا جاسكتا ہے حالانكہ وه زمین وآسمان كى بادشاہى میں كسى چیز كے بھى مالك نہیں؟ (السعدى: ۶۸۶)\nایك انسان كیسے فائده اٹھا سكتا ہے اس معرفت سے كہ الله كو چھوڑ كر جو غیروں كو پكارا جاتا ہے وه كسى چیز كےبھى مالك نہیں ہیں؟\nإِن تَدۡعُوهُمۡ لَا يَسۡمَعُواْ دُعَآءَكُمۡ وَلَوۡ سَمِعُواْ مَا ٱسۡتَجَابُواْ لَكُمۡۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُونَ بِشِرۡكِكُمۡۚ وَلَا يُنَبِّئُكَ مِثۡلُ خَبِيرٖ ١٤\nان بتوں كى حالت جب دنیا ہى میں ظاہر ہوگئى كہ وه كچھ بھى فائده نہیں پہنچا سكتے تو آخرت میں بھى ان كا معاملہ ظاہر ہوجائےگا كہ الله تعالىٰ انہیں وہاں بولنے كى طاقت دے گا اوروه ان كے شرك سے یعنى شرک کی جانب دعوت دینے اور راضى ہونے سے براءت كا اظہار كریں گے ۔ (ابن عاشور: ۲۲؍۲۸۳)\nالله سبحانہ وتعالىٰ نے دنیا وآخرت میں بتوں كى عبادت كا بطلان كیسے ظاہر كیا؟\n۞يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلۡفُقَرَآءُ إِلَى ٱللَّهِۖ وَٱللَّهُ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ ١٥\nچونكہ دلائل اور وعظ ونصیحت سے لوگوں كو خوب سمجھایا گیا پھر بھى ان كى حالت سے یہ ظاہر نہیں ہوا كہ وه اپنى ضلالت سے باز آئیں گے، بلكہ ایسا بھى ہوا كہ قوم کے معزز افرادخود پسندى اور غرور میں مبتلا ہوگئے اور انہیں یہ دھوکہ ہونے لگا کہ وہ مسلم جماعت میں شامل ہونے کے لئے پسندیدہ افراد ہیں۔ اور اس طرح وه شیطان كے پھندے میں مزید پھنستے چلے گئے اور اپنے شرک پر ڈٹے رہے، ایسى صورت میں مناسب ہوا كہ الله انہیں بتلادے كہ وه ان سے بے نیاز ہے، اور اسكا دین اس طرح كےلوگوں پر كبھى فخر نہیں كرسكتا، وه ضرور ایسے لوگوں كو فنا كے گھاٹ اتار كر ایسے لوگوں كو پیدا كرےگا جن پر دین اسلام فخر كرےگا۔ (ابن عاشور: ۲۲؍۲۸۵)\nاس آیت كےاندر تمام لوگوں كو فقر سے متصف كرنے میں كیا حكمت ہے؟\n۞يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلۡفُقَرَآءُ إِلَى ٱللَّهِۖ\nالله تبارك وتعالىٰ تمام لوگوں سے مخاطب ہے ، انہیں ان كے احوال واوصاف سے آگاه فرماتا ہے كہ وه ہر لحاظ سے الله تعالىٰ كے محتاج ہیں: وه وجود میں آنے كیلئے اس كے محتاج ہیں ، كہ اگر الله تعالىٰ ان كو وجود میں نہ لائے تو وه وجود میں نہیں سكتے۔ وه اپنے مختلف قوى، اعضاء اور جوارح كے حصول میں اس كے محتاج ہیں كہ اگر الله تعالىٰ ان كو یہ قوى عطا نہ كرے تو كسى كام كیلئے ان میں كوئى استعداد نہیں ہوسكتا۔ وه خوراك، رزق اور دیگر ظاہرى وباطنى نعمتوں كےحصول میں اسى كے محتاج ہیں كہ اگر اس كا فضل وكرم نہ ہو اور اگر وه ان امور كے حصول میں آسانى پیدا نہ كرے تو وه رزق اور دیگر نعمتیں حاصل نہیں كرسكتے۔وه اپنے مصائب وتكالیف، كرب وغم اور شدائد كو دور كرنے میں الله تعالىٰ كے محتاج ہیں كہ اگر الله تعالىٰ ان كى مصیبتوں اور كرب وغم كو دور اور ان كى عسرت كا ازالہ نہ كرے تو وه ہمیشہ ہمیشہ مصائب وشدائد میں گھرے رہیں۔ (السعدى: ۶۸۷)\nكیا لوگ صرف مال میں الله كے محتاج ہیں؟ چند ایسے وجوہات پر كچھ روشنى ڈالیں جس سے پتہ چلے كہ لوگ اپنے رب كے محتاج ہیں؟\n۞يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلۡفُقَرَآءُ إِلَى ٱللَّهِۖ وَٱللَّهُ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ ١٥\nجب الله تعالىٰ نے لوگوں كى محتاجگى اور ان سے اپنى بے نیازى ثابت كردى ، اور یہ كہ ہر بے نیاز كیلئے ضرورى نہیں كہ وه اپنى مالدارى سے دوسروں كو نفع پہنچائے جب تك كہ وه فیاض اور انعام كرنے والا نہ ہو، تو آخر میں الله تعالىٰ نے اپنى دوسرى صفت (الحميد) كا بھى ذكر كیا تاكہ یہ پتہ چل جائے كہ اسكى ذات بے نیاز ہونے كےساتھ اپنى مخلوق كو فائده بھى پہنچاتى ہے، ان كے ساتھ فیاضى اور ان پر انعام كر كے۔ (القرطبى: ۱۷؍۳۶۶)\nآیت كے اندر صفت حمید كے ساتھ صفت غنى كو كیوں ملایا گیا؟\nوَإِن تَدۡعُ مُثۡقَلَةٌ إِلَىٰ حِمۡلِهَا لَا يُحۡمَلۡ مِنۡهُ شَيۡءٞ وَلَوۡ كَانَ ذَا قُرۡبَىٰٓۗ\nابن عباس رضى الله عنہ نے فرمایا: ماں باپ اپنے بیٹے سے ملیں گے اور كہیں گے: بیٹے! میرے كچھ گناه تم اپنے اوپر اٹھا لو تو وه كہےگا: میں ایسا نہیں كرسكتا، میرا گناه میرے لئےكافى ہے۔(البغوى: ۳؍۶۲۱)\nقیامت كے روز تمہارے گناه كون اٹھائےگا؟\nإِنَّمَا تُنذِرُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ وَأَقَامُواْ ٱلصَّلَوٰةَۚ وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفۡسِهِۦۚ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ ١٨\nمطلب یہ ہے كہ ڈرانا اسى كیلئے مفید ہے جو اپنے رب سے ڈرتےہیں ، یہاں یہ مطلب نہیں ہے كہ ڈرانا صرف انہیں كے ساتھ خاص ہے۔ (ابن جزى: ۲؍۲۱۵)\nكیا آیت اس بات پر دلالت كرتى ہے كہ رسول و دعاۃ صرف انہیں لوگوں كو ڈراتےہیں جو الله سے ڈرنے والے ہیں ؟ اس كى وضاحت كریں.\nwords\nفُرَاتٌبهت ميٹھا.\nسَائِغٌحلق سے آساني سے اترنے والا.\nأُجَاجٌبهت سخت كھارا.\nمَوَاخِرَپاني كو چيرتي هيں.\nقِطمِيرٍكھجور كي گھٹلي پر باريك چھلكا.\nمُثقَلَةٌخطاؤوں سے بوجھل نفس.\nحِملِهَااس كے وه گناه جن سے وه بوجھل هے."],[437,"§فاطر\ndeeds\nآج ہى سے قرآن كر یم كا كچھ حصہ خاص كرلیں گرچہ وه تھوڑا ہى كیوں نہ ہو اور اسے روزآنہ پڑھتےرہیں.\nتكبیرۂ اولىٰ كے ساتھ باجماعت نماز ادا كیجئے.\nاپنے مال سے ایسا صدقہ كریں جسے صرف الله كے سوا كوئى نہ جان سكے، اور دكھاكر بھى صدقہ كریں تاكہ دوسرے لوگ آپ كى اقتداء كریں.\nguid\nاپنى زندگى میں خشیت الہى كو ثابت كریں آپ حقیقى اہل علم میں سےہوجائیں گے.\nقرآن پاك كى تلاوت زیاده سے زیاده كریں اس سے نصیحت پكڑتےہوئے اور اس میں غور وفكر كرتےہوئے.\nیہ ہمیشہ یاد ركھیں كہ وه تجارت جس میں كوئى خساره نہیں وه تجارت ہے جو الله كےساتھ كى جائے.\nrefl\nوَمَا يَسۡتَوِي ٱلۡأَحۡيَآءُ وَلَا ٱلۡأَمۡوَٰتُۚ إِنَّ ٱللَّهَ يُسۡمِعُ مَن يَشَآءُۖ وَمَآ أَنتَ بِمُسۡمِعٖ مَّن فِي ٱلۡقُبُورِ ٢٢\nیہ مومن كى مثال ہے كہ وه زنده كى طرح ہے ، اور جو مومن نہیں وه مرده كى طرح ہے، (إن الله يسمع من يشاء) الله جسے چاہتا ہے سناتاہے، یعنى جسے چاہتا ہے ہدایت دیتاہے (وما أنت بمسمع من في القبور) اور مردوں كو آپ نہیں سنا سكتے، یعنى اپنے دلائل اور وعظ ونصیحت كے ساتھ كافروں كو اپنى بات نہیں سناسكتے، اس طرح عدم احساس میں ان كى مثال مردوں كى سى ہے۔ (ابن جزى: ۲؍۲۱۵)\nاس آیت میں كافروں اور مردوں میں ایك بلیغ تمثیل پائى جاتى ہے، اس تعلق سے تشبیہ كے اسباب واضح كریں.\nوَمَا يَسۡتَوِي ٱلۡأَحۡيَآءُ وَلَا ٱلۡأَمۡوَٰتُۚ إِنَّ ٱللَّهَ يُسۡمِعُ مَن يَشَآءُۖ وَمَآ أَنتَ بِمُسۡمِعٖ مَّن فِي ٱلۡقُبُورِ ٢٢\nكفر كےسبب جو سب سے بڑى محرومى ہے وه قرآن پاك جیسى بلیغ اور سچى كتاب سے فائده نہ اٹھا پانا ہے۔ (ابن عاشور: ۲۲؍۲۹۵)\nدنیا میں كافر كیلئے سب سے بڑى محرومى كیا ہے؟\nأَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ ثَمَرَٰتٖ مُّخۡتَلِفًا أَلۡوَٰنُهَاۚ وَمِنَ ٱلۡجِبَالِ جُدَدُۢ بِيضٞ وَحُمۡرٞ مُّخۡتَلِفٌ أَلۡوَٰنُهَا وَغَرَابِيبُ سُودٞ ٢٧ وَمِنَ ٱلنَّاسِ وَٱلدَّوَآبِّ وَٱلۡأَنۡعَٰمِ مُخۡتَلِفٌ أَلۡوَٰنُهُۥ كَذَٰلِكَۗ\nالله تبارك وتعالىٰ ذكر فرماتا ہے كہ اس نے كائنات میں متضاد اشیاء كو تخلیق كیا جن كى اصل اور ماده ایك ہے، مگر اس كے باوجود ان میں فرق اور تفاوت ہے جو معروف اور سب پر عیاں ہے تاكہ بندے الله تعالىٰ كى قدرت كاملہ اور حكمت تامہ پر استدلال كریں پس ان كے درمیان تفاوت الله كى مشیت پر عقلى دلیل ہے، جس نے ہر ایك كو مخصوص رنگ اور وصف سے مختص كیا۔ یہ الله تعالىٰ كى قدرت وحکمت اور رحمت پر بھی دلیل ہے كہ اس نے ان كو اس اختلاف اور تفاوت کے ساتھ وجود بخشا۔ (السعدى: ۶۸۸)\nمخلوق كے متعدد، اوراسكے مختلف شكل ورنگ كے ہونے میں كونسى صفت الہیہ كا پتہ چلتاہے؟\nإِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْۗ إِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ ٢٨\nربیع بن انس رحمہ اللہ نے كہا: جس كے اندر الله تعالىٰ كى خشیت نہ ہو وه عالم نہیں ہے۔ اور ابن مسعود رضی اللہ عنہ سےروایت ہے كہ الله كى خشیت كیلئے علم كا ہونا كافى ہے اور اس پر غرور كرنا جہالت کے لئے كافى ہے۔ اور مجاہد رحمہ اللہ سے روایت ہے: فقیہ وہى ہے جو الله كا خوف ركھتاہو۔ (القرطبى: ۱۷؍۳۷۵- ۳۷۶)\nوه كون سى نمایاں صفت ہے جس سے ایك سچا طالب علم ممتا ز ہوتاہے؟\nإِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْۗ إِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ ٢٨\nیہاں علماء سے مراد وه لوگ ہیں جنہیں الله اور شریعت كى معرفت ہو، اور اس بارے میں علم كے حساب سے اسكى خشیت مضبوط ہوتى ہے، لیكن ایسا علم جس كا تعلق الله اور اسكے ثواب وعقاب کی حقیقی معرفت سے نہ ہو تو ایسے علوم صاحب علم کو الله كى خشیت سے كبھى قریب نہیں كرسكتے۔ (ابن عاشور: ۲۲؍۳۰۴)\nحقیقى عالم كون ہے؟\nإِنَّ ٱلَّذِينَ يَتۡلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ يَرۡجُونَ تِجَٰرَةٗ لَّن تَبُورَ ٢٩\nآیت كےاندر ان لوگوں كے ثواب كا ذكر ہے جو قرآن كى تلاوت كرتےہیں ، چنانچہ انہیں پر یہ صادق آئےگا كہ یہى لوگ ان لوگوں میں سے ہیں جو كتاب الله كى تلاوت كرتےہیں اور نماز قائم كرتےہیں، گرچہ قرآن میں تدبر نہیں پایا جاتا؛ كیونكہ تلاوت میں اجر وثواب كےساتھ كلام الله كے انوار سے روشنى بھى حاصل ہوتى ہے۔(ابن عاشور: ۲۲؍۲۹۷)\nكیا قرآن كى تلاوت كرنے والا ثواب پائےگا گرچہ تدبر نہ كرے؟\nإِنَّ ٱلَّذِينَ يَتۡلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ يَرۡجُونَ تِجَٰرَةٗ لَّن تَبُورَ ٢٩\nاس آیت كریمہ میں ان اہل ایمان كے اعمال میں اخلاص كى طرف اشاره ہے نیز اس امر كى طرف اشاره ہے كہ ان اعمال میں انكے مقاصد برے اور نیت فاسد نہیں ہے۔ (السعدى: ۶۸۹)\nالله تعالىٰ كے قول: (يرجون تجارة لن تبور) سے كس چیز كا پتہ چلتاہے؟\nwords\nالحَرُورُگرم هوائيں.\nوَبِالزُّبُرِوه كتابيں جن ميں بهت سارے احكام جمع هوں.\nنَكِيرِميرا انكار كرنا/ ميرا ان كو سزا دينا.\nجُدَدٌمختلف رنگوں اور نقوش والا رسته.\nوَغَرَابِيبُ سُودٌبهت زياده سياه / جيسے كوا.\nلَن تَبُورَوه هر گز ختم نه هوگا؛ هلاك نه هوگا."],[438,"§فاطر\ndeeds\nدعا کیجئے: “اَللّٰهُمَّ ارْزُقْنِىْ حِفْظَ كِتَابِكَ، وَالْعَمَلَ بِهٖ، وَالدَّعْوَةَ إِلَيْهِ” اے اللہ! مجھے قرآن کے حفظ، اس پر عمل کرنے اور اس کی جانب دعوت دینے کی توفیق عنایت فرما.\nاپنى مسجد كےاندر جماعت كے ساتھ پہلى صف میں نماز پڑھنے میں دوسروں سے سبقت كریں.\nایك پیغام بھیجیں جس میں یہ ذكر كریں كہ جسے اہل جنت كا لباس چاہئے تو وه دنیا كےاندر حرام لباس سے دور رہے.\nguid\nخود كو بڑا نہ سمجھیں اور نہ ہى اپنے عمل كو زیادہ سمجھیں ، دیکھیں یہ عائشہ رضی اللہ عنہا ہیں جو خود كو اپنے نفس پر ظلم كرنے والیوں میں سمجھتى تھیں.\nجان لیں كہ الله تعالىٰ جسے چن لیتاہے اسے كتاب الله كے علم وعمل كا وارث بنا دیتا ہے ، تو انہیں میں سے ہوجائیں.\nغور كریں كہ ہمارے رب نے اپنے نفس پر ظلم كرنےوالے كو كیسے اپنے چننده بندوں میں شامل كرلیاہے.\nrefl\nثُمَّ أَوۡرَثۡنَا ٱلۡكِتَٰبَ ٱلَّذِينَ ٱصۡطَفَيۡنَا مِنۡ عِبَادِنَاۖ فَمِنۡهُمۡ ظَالِمٞ لِّنَفۡسِهِۦ وَمِنۡهُم مُّقۡتَصِدٞ وَمِنۡهُمۡ سَابِقُۢ بِٱلۡخَيۡرَٰتِ بِإِذۡنِ ٱللَّهِۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ ٣٢\nعمر، ابن مسعود، ابن عباس، كعب ، عائشہ -رضى اللہ عنہم- اور بہت سے مفسرین كا قول ہے كہ یہ تینوں قسمیں محمد صلی اللہ علیہ وسلم كى امت میں موجود ہیں، چنانچہ اپنے نفس پر ظلم كرنے والا گنہگار ہے، نیكیوں میں سبقت كرنے والا متقى ہے اور میانہ روى والا ان دونوں كے درمیان ہے۔ (ابن جزى: ۲؍۲۱۷)\nآیت میں مذكور تینوں قسم كے لوگ كس امت سے تعلق رکھتے ہیں؟ یہ كون ہیں اور ان كى كیا صفات ہیں ؟\nوَمِنۡهُم مُّقۡتَصِدٞ وَمِنۡهُمۡ سَابِقُۢ بِٱلۡخَيۡرَٰتِ بِإِذۡنِ ٱللَّهِۚ\nاللہ تعالیٰ كا ارشاد: (بإذن الله) نیكیوں كى طرف سبقت كرنےوالے كى طرف راجع ہے تاكہ وہ اپنے عمل كےبارےمیں كسى دھوكے میں مبتلا نہ ہوجائے كیونكہ اس نے نیكیوں كى طرف سبقت صرف اللہ تعالىٰ كى توفیق اور اسكى مدد سے كى ہے، لہذا اس كو چاہئے كہ اللہ تعالىٰ نے اسے جس نعمت سے نوازا ہے وہ اس پر اللہ تعالىٰ كا شكر ادا كرے۔(السعدى: ۶۸۹)\nنیكیوں كى طرف سبقت كرنےوالے كے ساتھ (بإذن الله) كو خاص كیوں كیا گیا؟\nوَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَذۡهَبَ عَنَّا ٱلۡحَزَنَۖ إِنَّ رَبَّنَا لَغَفُورٞ شَكُورٌ ٣٤\nابن عباس رضی اللہ عنہ نے فرمایا: یہاں غم سے مراد دوزخ كا غم ہے۔ قتادہ رحمہ اللہ نے كہا: موت كا غم ہے۔ اور مقاتل رحمہ اللہ نے كہا: وہ غمگین ہوں گے كیونكہ انہیں نہیں معلوم ہوگا كہ اللہ تعالىٰ ان كے ساتھ كیا كرےگا۔ اور عكرمہ رحمہ اللہ نے كہا: گناہوں ، برائیوں كا غم اور نیكیوں كے مقبول نہ ہونے كا خوف مراد ہے۔ (البغوى: ۳؍۶۲۶)\nاہل ایمان كو دنیا میں كون سا غم ہوگا جسے اللہ تعالىٰ جنت میں ختم كردےگا؟\nٱلَّذِيٓ أَحَلَّنَا دَارَ ٱلۡمُقَامَةِ مِن فَضۡلِهِۦ لَا يَمَسُّنَا فِيهَا نَصَبٞ وَلَا يَمَسُّنَا فِيهَا لُغُوبٞ ٣٥\n(دار المقامة) سے مراد جنت ہے، اور مقامہ سے مرادٹھہرنا اور ٹھہرنے كى جگہ ہے، اور جنت كو دار المقامہ كہا گیا كیونكہ اہل جنت اس میں ہمیشہ ٹھہرے رہیں گے اور وہاں سے كبھى نہیں نكلیں گے۔ (ابن جزى: ۲؍۲۱۷)\nجنت كو دار المقامہ كیوں كہاگیا؟\nٱلَّذِيٓ أَحَلَّنَا دَارَ ٱلۡمُقَامَةِ مِن فَضۡلِهِۦ\nیعنى جس ذات نے ہمیں اس مقام ومرتبے سے نوازا ، وه اسكى رحمت ، احسان اور فضل سے ہے ، ہمارے اعمال اسكے برابر كبھى نہیں ہوسكتے۔ (ابن كثیر: ۴؍۵۳۵)\nكیا انسان مجرد اپنے عمل كى وجہ سے جنت میں جاسكتاہے؟ آیت كى روشنى میں اس كى وضاحت كریں.\nوَٱلَّذِينَ كَفَرُواْ لَهُمۡ نَارُ جَهَنَّمَ لَا يُقۡضَىٰ عَلَيۡهِمۡ فَيَمُوتُواْ وَلَا يُخَفَّفُ عَنۡهُم مِّنۡ عَذَابِهَاۚ كَذَٰلِكَ نَجۡزِي كُلَّ كَفُورٖ ٣٦\nاللہ تعالیٰ کا ارشاد: (لا يقضى) كا مفہوم ہے ان كى جان پورى نہیں جائےگى؛ كیونكہ اگر وه مرجائیں گے تو ان كے احساس ختم ہوجائیں گے اور انہیں راحت مل جائےگى۔ (ابن عطیہ : ۴؍۴۴۰)\nاہل دوزخ سے موت كى نفى كیوں كى گئى ہے؟\nوَهُمۡ يَصۡطَرِخُونَ فِيهَا رَبَّنَآ أَخۡرِجۡنَا نَعۡمَلۡ صَٰلِحًا غَيۡرَ ٱلَّذِي كُنَّا نَعۡمَلُۚ\nابن عباس رضی اللہ عنہ نے فرمایا: ہم لا الہ الا الله کہیں گے یعنی کفر كے بدلے ایمان لائیں گے، معصیت كےبدلے اطاعت کریں گے اور رسولوں كے حكم كى فرمانبردارى کریں گے۔ (القرطبى: ۱۷؍۳۸۸)\nوه كون سا عمل صالح ہوگا جس كى تمنا اہل دوزخ جہنم میں جانے كےبعد كریں گے؟\nwords\nظَالِمٌ لِنَفسِهِبعض گناه كا كام كرنے والا.\nمُقتَصِدٌواجبات اداكرنے والا؛ اور حرام سے بچنے والا.\nسَابِقٌ بِالخَيرَاتِنيك اعمال ؛ فرائض اور نفل كي كثرت كرنے والا.\nعَدنٍاقامت.\nلُغُوبٌتھكاوٹ / تنگي."],[439,"§فاطر\ndeeds\nآپ اور آپ كے ساتھى كسى ایسے عمل صالح كى آپس میں وصیت كریں جسے دونوں مل كر انجام تك پہونچائیں.\nالله كے اسمائے حسنىٰ (الحليم الغفور) كے ذریعے اسكى عبادت كریں اور دعا کریں: “يَا حَلِيْمُ اِحْلَمْ عَلَىَّ وَلَا تُعَذِّبْنِيْ، يَا غَفُورُ اغْفِرْ لِيْ وَارْحَمْنِيْ” یعنی اے حلیم! میرے ساتھ بردباری کا معاملہ کرتے ہوئے مجھے عذاب نہ دینا اور اے غفور! مجھے بخش دے اور مجھ پر رحم فرما.\nكوئى دستاویزى فلم، یا آتش فشاں پہاڑوں، یا زلزلوں یا سیلابوں كى تصویریں دیكھیں پھر ان میں الله تعالىٰ كى قدرت اور انسان كى كمزورى میں غور كریں.\nguid\nكفر اور معصیت سے بنده الله كے نزدیك مبغوض اور ذلیل ہوجاتاہے.\nیاد ركھیں كہ ظالموں كا آپس میں ایك دوسرے سے وعده كرنا محض دھوكہ اور جھوٹ ہوتاہے، لہذا ان سے دھوكہ كھانے سے بچیں.\nخوش رہیں اور ڈریں مت؛ كیونكہ برى چال چال چلنے والے ہى پر آتى ہے.\nrefl\nهُوَ ٱلَّذِي جَعَلَكُمۡ خَلَٰٓئِفَ فِي ٱلۡأَرۡضِۚ فَمَن كَفَرَ فَعَلَيۡهِ كُفۡرُهُۥۖ\nالله تعالىٰ فرمارہاہے كہ اے لوگو! جو الله كےساتھ كفر كرےگا تو اسكے كفر كا نقصان اسى كو ہوگا، اسكے علاوه كسى دوسرے كو نہیں ہوگا، كیونكہ اسكى سزا اسكے علاوه كوئى دوسرا نہیں بھكتے گا۔ (الطبرى: ۲۰؍۴۸۰)\nابن آدم كے كفر كا نقصان كسے ہوگا؟\nوَلَا يَزِيدُ ٱلۡكَٰفِرِينَ كُفۡرُهُمۡ عِندَ رَبِّهِمۡ إِلَّا مَقۡتٗاۖ\nیعنى جس طرح وه اپنے كفر پر اڑے رہیں گے اسى طرح الله تعالىٰ ان سے بغض ركھےگا برخلاف مومنین كے؛ كیونكہ جس طرح ان كى عمر زیاده ہوگى اور ان كا حسن عمل بھى بڑھتا رہے گا اسى طرح ان كا مقام ومرتبہ بھى جنت میں اونچا ہوتا رہےگا، اور انكا اجر بھى بڑھتا رہے گا، اور ان كا خالق اور بارى جو كہ رب العالمین ہے ان سے محبت كرےگا۔ (ابن كثیر: ۳؍۵۳۸)\nآیت كےاندر كافروں كےساتھ كفر كے عمل كا ذكر ہے ، تو مومنوں كےساتھ انكا ایمان كیا عمل كرےگا؟\nوَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِن جَآءَهُمۡ نَذِيرٞ لَّيَكُونُنَّ أَهۡدَىٰ مِنۡ إِحۡدَى ٱلۡأُمَمِۖ فَلَمَّا جَآءَهُمۡ نَذِيرٞ مَّا زَادَهُمۡ إِلَّا نُفُورًا ٤٢\nان كا یہ قسمیں کھانا كسى اچھے مقصد اور طلب حق كیلئے نہ تھا، اگر ایسا ہوتا تو ان كو ضرور اس كى توفیق عطا كردى جاتى لیكن ان كا قسمیں کھانا تو مخلوق اور حق كے مقابلے میں زمین پر تكبر كرنے اور اپنى بات میں مكر وفریب كرنے سے صادر ہوا تھا۔ ان كا مقصد محض فریب كارى تھا اور یہ ظاہر كرنا تھا كہ وه تو اہل حق اور حق كے متلاشى ہیں تو ساده لوح لوگ ان كے فریب میں مبتلا ہوكر ان كے پیچھے چل پڑے۔(السعدى: ۶۹۱)\nكیا ان كا قسمیں کھانا طلب حق كیلئے تھا؟\nٱسۡتِكۡبَارٗا فِي ٱلۡأَرۡضِ وَمَكۡرَ ٱلسَّيِّيِٕۚ وَلَا يَحِيقُ ٱلۡمَكۡرُ ٱلسَّيِّئُ إِلَّا بِأَهۡلِهِۦۚ\n(استكبارًا) یعنى ایمان سے ہٹ دھرمى كرنا، (ومكر السيِّئ) یعنى برے عمل كى چال، اور وه كفر ہے ، كمزوروں كو دھوكہ دینا اور انہیں ایمان سے پھیرنا ہے تاكہ ان كے پیروكاروں كى تعداد بڑھ جائے۔(القرطبى: ۱۷؍۳۶۹)\nانكے اس برى چال كى كیا حقیقت ہے جس نے انہیں عذاب كا مستحق بنایا تاكہ ہم اس سے بچ سكیں ؟\nٱسۡتِكۡبَارٗا فِي ٱلۡأَرۡضِ وَمَكۡرَ ٱلسَّيِّيِٕۚ وَلَا يَحِيقُ ٱلۡمَكۡرُ ٱلسَّيِّئُ إِلَّا بِأَهۡلِهِۦۚ فَهَلۡ يَنظُرُونَ إِلَّا سُنَّتَ ٱلۡأَوَّلِينَۚ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبۡدِيلٗاۖ وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحۡوِيلًا ٤٣\nانسان جب ایك دوسرے سے مامون نہیں ہوتے تو اجنبى بن كر رہتےہیں، اور ایك دوسرے كو نقصان پہنچانے اور اس كى تباہى كے در پہ ہوتےہیں، تاكہ دوسرے كو دھوكہ دیكر كامیاب ہوسكے اس دھوكہ میں خود واقع ہونے سے پہلے، جس کا انجام دنیا میں بڑے فساد کی صورت میں ہوتا ہے ، اور الله تعالىٰ فساد كو پسند نہیں كرتا۔(ابن عاشور: ۲۲؍۳۳۵)\nسماج میں امن وامان كے فقدان سے كیا آثار مرتب ہوتےہیں؟آیت كى روشنى میں اسے واضح كریں.\nفَهَلۡ يَنظُرُونَ إِلَّا سُنَّتَ ٱلۡأَوَّلِينَۚ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبۡدِيلٗاۖ وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحۡوِيلًا ٤٣\nالله تعالىٰ نے كافروں پر عذاب جارى كیا اور اسے ان كے اندر سنت بنادیا، اب وه ہر اس شخص كو عذاب دےگا جو اس كا مستحق ہوگا، كوئى اسے بدل نہیں سكتا، اور نہ ہى كوئى اپنے عذاب كو دوسرے كى طرف پھیر سكتاہے۔ (القرطبى: ۱۷؍۴۰۰)\nكیا گنہگاروں پر نزول عذاب كے تعلق سے الله كى سنت میں تبدیلى آسكتى ہے؟\nوَمَا كَانَ ٱللَّهُ لِيُعۡجِزَهُۥ مِن شَيۡءٖ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ عَلِيمٗا قَدِيرٗا ٤٤\nكسى كا اراده پورا اسى وقت نہیں ہوسكتا جب یا تو اراده پورا ہونے كى جگہ كا علم نہ ہو ، اور یہ احاطۂ علم كے منافى ہے، یا اس كےپورا كرنے كى طاقت نہ ہو، اور یہ قدرت عامہ كے منافى ہے۔ (ابن عاشور: ۲۲؍۳۳۹)\nالله تعالىٰ كى دونوں صفت: علم وقدرت پر آیت كو ختم كرنے سے كیا فائده ہے؟\nwords\nخَلاَئِفَزمين ميں ايك دوسرے كے جانشين.\nمَقتًابغض اور غضب.\nأَرَأَيتُممجھے بتاؤ تو سهي.\nبَيِّنَةٍ مِنهُاس كي طرف سے حجت /برهان\nغُرُورًادھوكه اور باطل.\nجَهدَ أَيمَانِهِمكوشش كركے سخت قسميں اٹھانے والے.\nيَحِيقُوه احاطه كرتا هے؛ ان پر نازل كرتا هے."],[440,"§يس ، فاطر\ndeeds\nكوئى ایسا وعظ یاد كریں جسے آپ نے سن ركھا ہو ،پھر ان میں مذكور نصیحتوں پر عمل كریں تاكہ مغفرت اور عمده اجر كے مستحق بن سكیں.\nایسا عمل كریں جسكا اثر مرنے كےبعد بھى باقى رہے، اور آج ہى ایسا كوئى عمل كر ڈالیں ، جیسے كہ كسى مسجد كى تعمیر میں امداد، یا كسى غیر مسلم كو اسلام كى طرف دعوت دینا، یا كسى جاہل كو كچھ سكھلانا، یا اس طرح كا كوئى اور اچھا عمل.\nمسجد پیدل جائیں تاكہ ہر ہر قدم پر اجر كو لكھا جائے.\nguid\nيقین ركھیں كہ جس كى بھى موت كا وقت آجائے گا وه ایك لمحہ كیلئے بھى موخر نہ ہوگا.\nعذاب جس پر ثابت ہوجائے اسے ڈرانا كوئى فائده نہیں پہونچائےگا.\nاگر كسى ظالم كے ظلم كا ڈر ہو تو یہ پڑھیں.\nrefl\nوَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُواْ مَا تَرَكَ عَلَىٰ ظَهۡرِهَا مِن دَآبَّةٖ\nابن مسعود رضی اللہ عنہ نے كہا: قریب ہے گبریلا اپنے بل ہى میں عذاب پاجائے كسى انسان كے گناه كےسبب۔ اور یحیىٰ بن أبی كثیر رحمہ اللہ نے كہا: ایك شخص نے كسى كو بھلائى كا حكم دیا اور برائى سے روكا تو اس سے ایك شخص نے كہا: تم اپنى فكر كرو؛ كیونكہ ظالم اپنا ہى نقصان كرےگا، تو ابو ہریره رضی اللہ عنہ نے كہا: تم نے جھوٹ كہا، الله كى قسم جس کے سوا كوئى معبود برحق نہیں، پھر كہا: اس ذات كى قسم جس كےہاتھ میں میرى جان ہے! ایك گوریا چڑیا اپنے گھونسلےمیں كمزور ہوكر مرجاتى ہے ظالم كے ظلم كى وجہ سے۔(القرطبى: ۱۷؍۴۰۱- ۴۰۲)\nكیا بندوں كےگناہوں كا اثر جانوروں اور چوپایوں تك پہونچ جاتاہے؟\nوَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُواْ مَا تَرَكَ عَلَىٰ ظَهۡرِهَا مِن دَآبَّةٖ وَلَٰكِن يُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۖ فَإِذَا جَآءَ أَجَلُهُمۡ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِيرَۢا ٤٥\nیہ انہیں نصیحت ہے كہ پكڑ میں تاخیر سے وه دھوكہ نہ كھائیں، اور اسے عاجزى سمجھ بیٹھیں، یا ان كے كرتوتوں پر الله كى رضامندى سمجھ بیٹھیں، كیونكہ انہیں لوگوں نے كہا ہے: ﴿وَإِذۡ قَالُواْ ٱللَّهُمَّ إِن كَانَ هَٰذَا هُوَ ٱلۡحَقَّ مِنۡ عِندِكَ فَأَمۡطِرۡ عَلَيۡنَا حِجَارَةٗ مِّنَ ٱلسَّمَآءِ أَوِ ٱئۡتِنَا بِعَذَابٍ أَلِيمٖ﴾ [الانفال: ۳۲] یعنى جب انہوں نے كہا: اے الله! اگر یہى تیرے نزدیك حق پر ہیں تو ہم پر آسمان سے پتھر كى بارش كردے یا ہم پر دردناك عذاب نازل كردے) ۔ چنانچہ انہیں یہ بتلا رہا ہے كہ بتقاضائےحکمت الٰہی الله كے عذاب كا ایك وقت ہوتا ہے ، اس میں دوسرى امتوں كى مصلحتوں كى رعایت بھى ہوتى ہے، یا دوسرے آنے والى نسل كا بقا بھى ہوتاہے۔ (ابن عاشور: ۲۲؍۳۳۹)\nمشرك كے سزا كى تاخیر میں اسكى حالت كے صحیح ہونے كى دلیل نہیں ہے، آیت كریمہ نے اسے كیسے واضح كیا ہے؟\nوَٱلۡقُرۡءَانِ ٱلۡحَكِيمِ ٢ إِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ ٣\nقرآن عظیم آپ صلی اللہ علیہ وسلم كى رسالت پر ہمیشہ رہنے والى قوى ترین دلیل ہے۔ قرآن حكیم كى حقانیت كے تمام دلائل درا صل رسول الله صلی اللہ علیہ وسلم كى رسالت كے دلائل ہیں۔(السعدى: ۶۹۲)\nنبى كریم صلی اللہ علیہ وسلم كى رسالت كیلئے سب سے قوى ترین دلیل كیا ہے؟\nتَنزِيلَ ٱلۡعَزِيزِ ٱلرَّحِيمِ ٥\nالله تعالىٰ نے اس قرآن كو اپنى قدرت كاملہ سے تغیر وتبدل سے محفوظ فرمایا، اسكے ذریعے سے اپنے بندوں كو اپنى بےپایاں رحمت كے سائے میں لے لیا جو انہیں اس كے دار رحمت میں پہنچاتى ہے۔ بنابریں الله تعالىٰ نے اس آیت كریمہ كو اپنے دو كریم ناموں (العزيز) اور (الرحمي) پر ختم فرمایا۔(السعدى: ۶۹۲)\nآیت كریمہ كو ان دو كریم ناموں (العزيز) اور (الرحيم) پر ختم كیوں كیا گیا؟\nإِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكۡرَ وَخَشِيَ ٱلرَّحۡمَٰنَ بِٱلۡغَيۡبِۖ فَبَشِّرۡهُ بِمَغۡفِرَةٖ وَأَجۡرٖ كَرِيمٍ ١١\nاسم جلالہ (اللّٰه) نہ لاكر یہاں صفت (الرحمن) لایا گیا ہے اسكى دو وجہیں ہیں: (۱): كیونكہ مشركین اسم رحمٰن كا انكار كرتےتھے جیسا كہ ارشاد بارى ہے: ﴿قَالُواْ وَمَا ٱلرَّحۡمَٰنُ﴾ [الفرقان: ۶۰]مشرکین کہتے ہیں یہ رحمٰن کون ہے؟۔ (۲): اس بات كى طرف اشاره كہ اسكى رحمت عدم خشیت كا تقاضہ نہیں كرتى ہے، چنانچہ ایك مومن الله سے ڈرتا ہے جبكہ وه جانتا ہے كہ اسكى رحمت اسكے ساتھ ہے، پھر وه اسكى رحمت كى امید كرتاہے۔(ابن عاشور: ۲۲؍۳۵۴)\nآیت كریمہ كےاندر لفظ جلالہ (اللّٰه) كو چھوڑ كر (الرحمن) كى صفت كو كیوں لایا گیا؟\nإِنَّا نَحۡنُ نُحۡيِ ٱلۡمَوۡتَىٰ وَنَكۡتُبُ مَا قَدَّمُواْ وَءَاثَٰرَهُمۡۚ وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ فِيٓ إِمَامٖ مُّبِينٖ ١٢\nآدمى كے آثار جو باقى ره جاتے ہیں اسكے مرنے كےبعد انہیں یاد كیا جاتا ہےاس پر اسےبدلہ دیاجائے گا۔ وه برائى اور بھلائى سب ہوسكتےہیں، یعنى اچھا اثر بھى ہوسكتا ہے جیسے كوئى علم جسے لوگوں كو سكھلایا ہو یا كتاب جسے لكھا ہو، اور برا اثربھی ہوسکتا ہے جیسے كوئى منصب جس پر كسى ظالم مسلمان كو بیٹھا دیا ہو، یا ایسى كوئى چیز ایجاد کی ہوجو الله كے ذكر سے غافل كرنے والى ہو جیسے میوزك گانا اور لہوولعب كى چیزیں ایجاد كردے، اسى طرح ہر اچھا اور برا طریقہ جسے بعد میں لوگ اپنا لیں۔ (القرطبى: ۱۷؍۴۲۰)\nوفات كے بعد اچھا اثر چھوڑ كر جانے كى كیا اہمیت ہے؟ اور اسى طرح برا اثر چھوڑ كر جانے كا كیا انجام ہے؟\nإِنَّا نَحۡنُ نُحۡيِ ٱلۡمَوۡتَىٰ وَنَكۡتُبُ مَا قَدَّمُواْ وَءَاثَٰرَهُمۡۚ\nاس سے مراد وه آثار خیر اور آثار شر ہیں جنہیں وه اپنى زندگى میں اور مرنے كے بعد وجود میں لانے كا سبب بنے اس مقام پر الله تعالىٰ كى طرف دعوت دینے اور ہر طریقے اور ذریعے سے اسكى طرف جانے والے راستے كى نشاندہى كرنے كى عظمت واضح ہوجاتى ہے۔ برائى كى طرف دعوت دینے اور اسكو رائج كرنے والا سب سے گھٹیا مخلوق ، سب سے بڑا مجرم اور سب سے زیاده گناہوں كا بوجھ اٹھانے والا ہے۔ (السعدى: ۶۹۳)\nاس آیت كى روشنى میں دعوت الى الله كا مقام ومرتبہ واضح كریں.\nwords\nفِي أَعنَاقِهِم أَغلاَلًاان كے هاتھ گردن ميں بندھ گئے۔ شدت اعراض سے تمثيل هے.\nمُقمَحُونَسركو اوپر اٹھائے هوئے/ وه سر جھكا نهيں سكتے تھے.\nفَأَغشَينَاهُمهم نے ان كي آنكھوں كو اندھا كرديا هے.\nوَآثَارَهُمان كے ايجاد كرده كام ۔ خير و شر كے باقي رهنے والے كام."],[441,"§يس\ndeeds\nنماز سے غافل لوگوں كى كسى جماعت كےپاس جائیں اور انہیں اسكى ادائیگى كى نصیحت كریں.\nكسى نیك شخص یا كسى داعى كى مدد كریں اور اسكى فضیلت وسیرت واضح كریں ، پھر اسے کسی پیغام یا كسى بھى وسیلے سے نشر كریں.\nحق كى تبلیغ كركے یا كسى منكر پر نكیر كركے الله كےیہاں عذر پیش كریں.\nguid\nرسولوں كى پیروى كریں اور ان کے آثار كو اپنائیں.\nاپنى دعوت پر كسى اجر كا سوال نہ كریں، كیونكہ یہ قبول كے اسباب میں سے ہے.\nلوگوں كى ہدایت چاہیں نہ كہ ان كى ہلاكت، كیونكہ یہ ایك عظیم داعى كے بلند اخلاق كا حصہ ہے.\nrefl\nوَٱضۡرِبۡ لَهُم مَّثَلًا أَصۡحَٰبَ ٱلۡقَرۡيَةِ\nاگر بستى كے تعین میں كوئى فائده ہوتا تو الله تعالىٰ ضرور اسكا تعین فرمادیتا ۔اس سے آپ كو معلوم ہوجائےگا كہ علم صحیح كا طریق حقائق كےسامنے سرتسلیم خم كرنا اور ان امور سےتعرض كو ترك كرنا ہے جن كا كوئى فائده نہیں، اور اس طرح نفس پاك ہوتا ہے اور علم میں اضافہ ہوتا ہے ، جبكہ جاہل سمجھتا ہے كہ علم میں اضافہ ان اقوال كےبیان كرنے سے ہے جن كى كوئى دلیل وبرہان نہیں اور ان اقوال كو بیان كرنے سے ذہن كو تشویش میں مبتلا كرنے اور اسے مشكوك امور كا عادى بنانے كے سوا كوئى فائده نہیں۔ (السعدى: ۶۹۳)\nقرآن كے مبہم آیات كے ساتھ تعامل كا بہتر طریقہ كیا ہے؟ اوركیوں؟\nقَالُواْ طَٰٓئِرُكُم مَّعَكُمۡ أَئِن ذُكِّرۡتُمۚ بَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ ١٩\nرسولوں كا كہنا: (طائِرُكُم مَعَكُم)(تمہارى بدشگونى تمہارےساتھ) اسكامطلب یہ ہے کہ تمہارى قسمت اور تمہارا اچھا براانجام تمہارے ساتھ ہےیعنى تمہارے كرتوت، اور تمہارى كمائى وه سب ہمارى وجہ سے نہیں بلكہ تمہارے ظلم اور كفركى وجہ سے ہے ، اور یہى تفسیراور مفہوم دیگر لوگوں نے بھى بتلائى ہے۔ قسمت اور نصیب كواستعارہ کے طورپر(طَآئِر) كہاگیا ہے،یعنى پرندے كےاندر غور وفكر كرنے سے جو كچھ حاصل ہوتا ہے۔ (ابن عطیہ: ۴؍۴۵۰)\nآیت كےاندر تردید ہے اس شخص پر جو بدشگونى كرتا ہو ، اس كى وضاحت كریں.\nوَجَآءَ مِنۡ أَقۡصَا ٱلۡمَدِينَةِ رَجُلٞ يَسۡعَىٰ قَالَ يَٰقَوۡمِ ٱتَّبِعُواْ ٱلۡمُرۡسَلِينَ ٢٠\nآدمى كى صفت (سعى) یعنى دوڑنے سے لائى گئى ہے جو اس بات كا فائده دیتا ہے كہ اس آدمى نے آنے میں جلدى كى تھى، اسے یہ بات معلوم ہوئی تھی کہ شہر والے رسولوں کو مارنے یا ان کو سزا دینے کا ارادہ کئےہوئے ہیں، چنانچہ اس نے نصیحت كرنا چاہى ان پر اور رسولوں پر خوف كھاتےہوئے۔ اور یہ اس آدمى كى تعریف ہے جس سے یہ پتہ چلتا ہے كہ یہ شخص ان قابل اقتداء لوگوں میں سے ہے جو منكر اور برائیوں كے مٹانے میں جلدى كرتےہیں۔ (ابن عاشور : ۲۲؍۳۶۶)\nآیت كریمہ كےاندر جملۂ فعلیہ (يسعى) لانے كا كیا فائده ہے؟\nوَجَآءَ مِنۡ أَقۡصَا ٱلۡمَدِينَةِ رَجُلٞ يَسۡعَىٰ قَالَ يَٰقَوۡمِ ٱتَّبِعُواْ ٱلۡمُرۡسَلِينَ ٢٠\n(من أقصى المدينة) كو (رجل) پر مقدم كرنے سے شہر میں كنارے اور دور علاقوں میں رہنے والوں كى تعریف كاپتہ چل رہا ہے اور یہ كہ شہر كے مضافات میں رہنے والوں میں جو بھلائى ہوتى ہے وه درمیان شہر میں رہنے والوں میں نہیں ہوتى ہے ، اور یہ كہ كمزور طبقہ ایمان كى طرف جلدى كرتا ہے، كیونكہ انہیں حق اپنانے سے وه سارى آشائس اور بڑائیاں نہیں روك سكتیں جو قوم كے سرداروں كو روك دیتى ہیں، اور عام طور سے ایسے لوگ شہر كے درمیان میں رہتےہیں۔ (ابن عاشور: ۲۲؍۳۶۵)\n(من أقصى المدينة) كو (رجل) پر مقدم كیوں كیا گیا؟\nٱتَّبِعُواْ مَن لَّا يَسۡـَٔلُكُمۡ أَجۡرٗا وَهُم مُّهۡتَدُونَ ٢١\nیعنى یہ رسول تم سے ایمان لانے كى وجہ سے اجرت كا سوال نہیں كریں گے، اس طرح تم ان كے ساتھ اپنى دنیا میں سے كچھ بھى خساره نہیں اٹھاؤ گے، جبكہ ساتھ ہى ہدایت پاكر اپنے دین میں نفع ہى اٹھاؤ گے۔ (ابن جزى: ۲؍۲۲۲)\nآیت میں سچے داعى كے د و عوامل كا ذكر ہے ، وه كیا ہیں؟\nٱتَّبِعُواْ مَن لَّا يَسۡـَٔلُكُمۡ أَجۡرٗا وَهُم مُّهۡتَدُونَ ٢١\n(اتبعوا من لا يسألكم أجرًا) یعنى اس شخص كى اتباع كرو جو تمہارى ایسی خیر خواہى كرتا ہے ، جس میں تمہارے لئے بھلائى ہے، وه تم سے اس خیرخواہى اور راہنمائى پر تمہارے مال كا مطالبہ كرتا ہے نہ كوئى اجر چاہتا ہے اور جس كا یہ وصف ہو وه قابل اتبا ع ہوتا ہے۔ باقى رہا یہ اعتراض كہ جو كسى اجرت كے بغیر دعوت دیتا ہے تو ہو سكتا ہے وه حق پر نہ ہو ، چنانچہ اس اعتر اض كو رد كرنے كیلئے آگے الله تعالىٰ نے فرمایا: (وهم مهتدون)“اور وه ہدایت یافتہ ہیں” ؛ كیونكہ وه صرف اسى چیز كى طرف دعوت دیتےہیں جس كے اچھا ہونے پر عقل صحیح گواہى دیتى ہے اور صرف اسى چیز سے روكتےہیں جس كے قبیح ہونے پر عقل صحیح گواہى دیتى ہے۔ (السعدى: ۶۹۴)\nآیت كریمہ ارشاد بارى : (وهم مهتدون) پر ختم كیوں كى گئى؟\nقِيلَ ٱدۡخُلِ ٱلۡجَنَّةَۖ قَالَ يَٰلَيۡتَ قَوۡمِي يَعۡلَمُونَ ٢٦ بِمَا غَفَرَ لِي رَبِّي وَجَعَلَنِي مِنَ ٱلۡمُكۡرَمِينَ ٢٧\nاس آیت كےاندر بہت بڑى تنبیہ ہے ، چنانچہ یہ آیت غصہ پى جانے ، جاہلوں كےساتھ بردبارى كرنے، شریروں اور ظالموں كے جھنڈ میں رہنے والوں پر نرمى برتنے، ایسے لوگوں كو ان سے نكالنے كى كوشش و نرمى اختیار كرنے اور ایسے لوگوں پر ہنسنے اور ان پر بددعا كرنے سے باز رہنےكے وجوب پر دلالت كرتى ہے، كیونكہ آپ دیكھ رہے ہیں كہ كیسے اس نے خیر كى تمنا كى اپنے قاتلوں اور سازش كرنے والوں كیلئے ، جبكہ ساتھ ہى وه بتوں كے پجارى كافر تھے۔ (القرطبى: ۱۷؍۴۳۳)\nوه كون سا عظیم اخلاق ہے جسے مومن اس آیت سے سیكھتا ہے؟\nwords\nفَعَزَّزنَاهم نے ان كي تائيد كي/ ان كو قوت دي.\nتَطَيَّرنَا بِكُمهم نے تم سے بد فالي پكڑي.\nطَائِرُكُم مَعَكُمتمهاري نحوست/ تمهارے شرك اور برائي كے اعمال تم پر هي پڑيں گے.\nأَئِن ذُكِّرتُمكيا تمهيں نصيحت كي گئي هے؟تم نحوست پكڑتے هو.\nيَسعَىوه تيزي سے چلتا.\nفَطَرَنِياس نے مجھے پيدا كيا."],[442,"§يس\ndeeds\nقرآن میں مذكور انبیاء کرام كے قصوں میں سے كوئى بھی قصہ پڑھئے اوران کی قوم جیسے قوم فرعون اور قوم عاد وغیره پر جو عذاب آیا ہے اس پر غور کیجئے.\nغلہ جات یا پھل جو آپ كھاتےہیں ان کو زمین میں بونے سے لیكر آپ تك پہنچنے كے تمام مراحل پر غور كیجئے، پھر الله كى بیشمار نعمتوں پر اسكا شكر بجا لائیے.\nآپ صبح كے وقت یہ دعاء پڑھئے: اَللّٰهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوْتُ وَإِلَيْكَ النُّشُوْرُ: (اے اللہ! تیرے ہی فضل سے ہم نے صبح کی اور تیرے ہی فضل سے ہم نے شام کی اور تیرے ہی نام سے ہم زندہ ہوتے ہیں اور تیرے ہی نام سے ہم مرتے ہیں اور تیرے ہی طرف لوٹنا ہے) اور شام میں یہ دعاء: اَللّٰهُمَّ بِكَ أَمْسَيْنَا وَبِكَ أَصْبَحْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوْتُ وَإِلَيْكَ الْمَصِيْرُ: (اے اللہ! تیرے ہی فضل سے ہم نے شام کی اور تیرے ہی فضل سے ہم نے صبح کی اور تیرے ہی نام سے ہم زندہ ہوتے ہیں اور تیرے ہی نام سے ہم مرتے ہیں اور تیری ہی طرف اٹھ کر جانا ہے) .\nguid\nنافرمان بندوں كے حق میں الله تعالىٰ كى كڑى سزا کا تذکرہ كہ اس نے ایك چیخ كے ذریعے سب کو ہلاك كردیا.\nتمام مخلوقات كى اس بارے میں یكسانیت یاد كیجئے كہ سب کو الله كے روبرو حاضر كیا جائے گا.\nالله تعالىٰ كى مخلوقات میں غور كیجئے، زمین اور اس كے پھلوں ، آسمان اور اسكے ستاروں كےبارے میں سوچئے.\nrefl\n۞وَمَآ أَنزَلۡنَا عَلَىٰ قَوۡمِهِۦ مِنۢ بَعۡدِهِۦ مِن جُندٖ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ ٢٨\nاس کا معنی یہ ہے: کہ الله نے انہیں جبریل علیہ السلام كى ایك چیخ سے ہلاك وبرباد كردیا، اور اس كیلئے آسمان سے كوئى لشكر اتارنے كى ضرورت نہیں پڑى؛ كیونكہ اس كے مقابلے میں لوگ انتہائى كمتر ہیں۔ (ابن جزى: ۲؍۲۲۳)\nآیت كى روشنى میں بستى والوں كى كمزورى بیان كیجئے اور بتائیے كہ اگر الله انہیں عذاب دینا چاہے تو یہ اسكے لئے كتنا آسان ہے.\n۞وَمَآ أَنزَلۡنَا عَلَىٰ قَوۡمِهِۦ مِنۢ بَعۡدِهِۦ مِن جُندٖ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ ٢٨\nیعنى انہیں سزا دینے اور ہلاك كرنے كیلئے ہمیں آسمان سے كوئى لشكر اتارنے کی ضرورت نہیں پڑی (وما كنا منزلين) اور ہم (كسى قوم كى ہلاكت كیلئے) فرشتوں كو اتارا نہیں كرتے اسكى ضرورت اس لئے نہیں ہے كیونكہ الله كا اقتدار جتنا عظیم ہے، بنو آدم اتنے ہى كمزور ہیں ، الله پاك كى جانب سے معمولى عذاب ہى انكے لئے كافى ہے۔ (السعدى:۶۹۵)\nاس آیت كى روشنى میں انسان کی كمزورى واضح كیجئے.\nيَٰحَسۡرَةً عَلَى ٱلۡعِبَادِۚ مَا يَأۡتِيهِم مِّن رَّسُولٍ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ٣٠\nاللہ کے رسولوں علیہم السلام کا مزاق اڑانے کی وجہ سےبندے خود اپنے آپ پرحسرت وندامت اور افسوس كا اظہار کریں گے۔\nبندوں كى جانب سے اظہار حسرت كا سبب بیان كیجئے.\nوَءَايَةٞ لَّهُمُ ٱلۡأَرۡضُ ٱلۡمَيۡتَةُ أَحۡيَيۡنَٰهَا وَأَخۡرَجۡنَا مِنۡهَا حَبّٗا فَمِنۡهُ يَأۡكُلُونَ ٣٣\nالله تعالىٰ نے لوگوں کواس مثال كے ذریعے مردوں كو زنده كرنے پر تنبیہ فرمائى ہے،اور انہیں اپنى توحید اور اپنے كمال قدرت كى یاد دلائى ہےوہ مثال یہ ہے كہ الله تعالیٰ نے مرده زمین سے گھاس پھوس اور غلے جات پیدا فرمایا ہے۔ (القرطبى: ۱۷؍۴۴۰)\nیہاں مرده زمین کو ز نده كرنے کے تذکرہ كافائده كیا ہے؟\nسُبۡحَٰنَ ٱلَّذِي خَلَقَ ٱلۡأَزۡوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ وَمِنۡ أَنفُسِهِمۡ وَمِمَّا لَا يَعۡلَمُونَ ٣٦\nیعنى ان لوگوں پر تعجب ہے كہ یہ سارى نشانیاں دیكھنے كے باوجود بھى كفر كرتےہیں، یہاں معلوم ہوا كہ اگر كوئى كسى چیز پر تعجب كرے تو \"سبحان الله\" كہے۔(القرطبى: ۱۷؍۴۴۱)\nانسان كسى چیز پر تعجب كے وقت كیا كہے؟\nوَءَايَةٞ لَّهُمُ ٱلَّيۡلُ نَسۡلَخُ مِنۡهُ ٱلنَّهَارَ فَإِذَا هُم مُّظۡلِمُونَ ٣٧ وَٱلشَّمۡسُ تَجۡرِي لِمُسۡتَقَرّٖ لَّهَاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ ٣٨ وَٱلۡقَمَرَ قَدَّرۡنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلۡعُرۡجُونِ ٱلۡقَدِيمِ ٣٩ لَا ٱلشَّمۡسُ يَنۢبَغِي لَهَآ أَن تُدۡرِكَ ٱلۡقَمَرَ وَلَا ٱلَّيۡلُ سَابِقُ ٱلنَّهَارِۚ وَكُلّٞ فِي فَلَكٖ يَسۡبَحُونَ ٤٠\nیہ ساری چیزیں خالق کائنات اور اس کی صفات اور یہاں پر بطور خاص صفت قدرت، حکمت اور علم کی واضح دلیلیں ہیں۔(السعدى: ۶۹۶)\nاللہ تعالیٰ کی وہ نمایاں صفتیں کیا کیا ہیں جن پر مذكوره آیتیں دلالت كررہى ہیں؟\nوَٱلشَّمۡسُ تَجۡرِي لِمُسۡتَقَرّٖ لَّهَاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ ٣٨\nاللہ تعالیٰ نےیہاں عزیز اور علیم دو صفات کا ذكر فرمایا ہے، اور ایسا ستاروں كى گردش كے نظام سے متعلق ان كے معانى كى مناسبت كیوجہ سےہے۔ کیونکہ صفت عزت عظیم سیارے كى تسخیر کے لئے موزوں ہے جبکہ صفت علم اس دقیق اور منفرد نظام کے لئے مناسب ہے۔ (ابن عاشور: ۲۳؍۲۱)\nآیت كریمہ كو عزیز اور علیم كى صفت سے ختم كرنے كى كیا مناسبت ہے؟\nwords\nخَامِدُونَمرنے والے؛ ختم هوجانے والے.\nمُحضَرُونَجزاء و حساب كے ليے حاضر كئے جانے والے.\nنَسلَخُهم اسے كھينچ كر نكالتے هيں.\nكَالعُرجُونِ القَدِيمِجيسے باريكي كي وجه سے مڑي هوئي ٹهني ۔ پيلي رنگت والي.\nيَسبَحُونَوه چلتے هيں."],[443,"§يس\ndeeds\nذرا سوچئے كہ اگر نقل وحمل كے جدید وسائل نہ ہوتے تو آپ كو كتنى مشكلات كا سامنا كرنا پڑتا۔ الله نے ہمارے لئے ان وسائل كو مسخر كیا ہے ، لہذا اس پر الله كا شكر ادا كیجئے.\nالله تعالىٰ سے الحاح واصرار كے ساتھ ان الفاظ میں مانگئے: “اَللّٰهُمَّ اِنِّيْ اَعُوْذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوْبَتِكَ” اے اللہ میں تیرے غصے سے تیری رضا کی پناہ چاہتا ہوں اور تیری سزا سے تیری معافی کی پناہ چاہتا ہوں.\nاپنے مال كا كچھ حصہ فقراء ومساكین میں سے كسى پر صدقہ كیجئے.\nguid\nیہ انسانی كمزورى ہے كہ نوح علیہ السلام كے زمانے میں ان کی نسل كى بقاء كیلئے انہیں ایك كشتى كى ضرورت پیش آئى.\nالله تعالىٰ كى رحمت ہى بندے كو دنیاوى اور اخروى عذاب سے نجات دلا سكتى ہے.\nجب آپ كوئى آیت یا نصیحت سنیں تو اس پر دل سے متوجہ ہوں اور اس پر عمل شروع كردیں.\nrefl\nوَءَايَةٞ لَّهُمۡ أَنَّا حَمَلۡنَا ذُرِّيَّتَهُمۡ فِي ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ٤١\nذریت كا ذكر فرمایا ہے، کیونکہ یہ سفر سے عاجز ہوتی ہے، لہذا ان میں نعمت وانعام زیاده آسان ہے۔ (ابن عطیہ : ۴؍۴۵۵)\nآیت میں ذریت كے ذكر كى كیا وجہ ہے؟\nمَا يَنظُرُونَ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ تَأۡخُذُهُمۡ وَهُمۡ يَخِصِّمُونَ ٤٩\n(وهم يخِصِّمون) وه لوگ باہم لڑائى جھگڑے میں ہوں گے، قیامت سے غافل ہوں گے اور باہم لڑائى اور بحث وتكرار كى حالت میں ان كے دل میں قیامت كا خیال تك نہیں گزرے گا، اور یہ چیز (بحث وتكرار) عموما غفلت كے وقت رونما ہوتى ہے۔ (السعدی : ۶۹۷)\nدیگر اوقات كو چھوڑ كر باہم لڑائى جھگڑے كے وقت كو بطور خاص كیوں ذكر كیا گیا ہے؟\nمَا يَنظُرُونَ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ تَأۡخُذُهُمۡ وَهُمۡ يَخِصِّمُونَ ٤٩\nیعنى وه لوگ دنیاوى معاملات اور خرید وفروخت میں باہم الجھے ہوں گے، بازاروں اور مجالس میں بكواس كررہے ہوں گے۔(البغوى: ۳؍۶۴۳)\nان بندوں كى غفلت كا حال بیان كیجئے جن میں قیامت قائم ہوگى.\nفَلَا يَسۡتَطِيعُونَ تَوۡصِيَةٗ وَلَآ إِلَىٰٓ أَهۡلِهِمۡ يَرۡجِعُونَ ٥٠\nیہاں بطور خاص اہل وعیال كا ذكر كیا گیا ہے، اس لئے كہ اس گھڑى آدمی کیلئے اپنے گھروالوں سے بات كرنا غیروں كے مقابلے میں زیاده اہم ہے اور یہ انسانی فطرت کا اہم تقاضہ بھی ہے۔ (ابن عطیہ: ۴؍۴۵۷)\nاہل و عیال کا ذکر کسی خاص وجہ سے کیاگیا ہے وہ وجہ کیا ہے؟\nقَالُواْ يَٰوَيۡلَنَا مَنۢ بَعَثَنَا مِن مَّرۡقَدِنَاۜ هَٰذَا مَا وَعَدَ ٱلرَّحۡمَٰنُ وَصَدَقَ ٱلۡمُرۡسَلُونَ ٥٢\nاس کی تفسیر میں كہا گیا ہے: كہ جب كافر ایك دوسرے سے كہیں گے كہ(من بعثنا من مرقدنا) (ہمارى خواب گاہوں سے ہمیں كس نے جگا دیا؟) تو اس وقت جب وه ان چیزوں كا اپنى آنكھوں سے مشاہده کر لیں گےجن سے رسولوں نے انہیں باخبر كیا تھا، تب وہ رسولوں کی تصدیق کریں گے اور كہیں گے:(هذا ما وعد الرحمن وصدق المرسلون) یہى تو ہے جس كا رحمان نے وعده كیا تھا، اور رسولوں نے سچ سچ كہہ دیا تھا۔ مگر ہم نے جھٹلا دیا تھا ، پھر وه ایسے وقت اقرار كرینگے جب اقرار کرنا بے سود ہوگا۔ (القرطبى: ۱۷؍۴۶۵)\nایمان نہ لانے اور توبہ نہ كرنے پر كافروں كى ندامت كب ظاہر ہوگى؟\nقَالُواْ يَٰوَيۡلَنَا مَنۢ بَعَثَنَا مِن مَّرۡقَدِنَاۜ\nاس سے مراد ان كى وه قبریں ہیں جن كے بارے میں دنیا كے اندر وه یہ اعتقاد ركھتےتھے كہ اس سے دوباره اٹھائے نہیں جائیں گے، پھر جب محشر میں اپنى جھٹلائى ہوئى باتوں كا خود معائنہ كرلیں گے، تب كہیں گے: ہائے ہمارى بربادى! ہمیں ہمارى خواب گاہوں سے كس نے جگادیا؟ اس سے انكى قبروں میں ان کے عذاب کی نفی نہیں ہوتی ہے، بلكہ بعد میں جو شدت اور ہولناكى دیكھیں گے اس كے مقابلے میں انہیں قبر كى زندگى خواب كى طرح محسوس ہوگى۔ (ابن كثیر: ۳؍۵۵۲)\nكیا مشركین كے اس قول : (من بعثنا من مرقدنا) سے عذاب قبر كى نفى ہوتى ہے؟\nهَٰذَا مَا وَعَدَ ٱلرَّحۡمَٰنُ وَصَدَقَ ٱلۡمُرۡسَلُونَ ٥٢\nآپ یہ مت گمان كیجئے كہ یہاں رحمٰن كا ذكر محض اس كے وعدے كى خبر دینے کے لئے کیاگیا ہے بلكہ اسے ذکرکرکے یہ بتانا مقصود ہے کہ اس ہولناکی کے دن الله كى ایسى رحمت كا مشاہده كرینگے جو ان كےخواب وخیال تک میں نہ گزرا ہوگا جیسا كہ الله نے فرمایا: اس دن صحیح طور پر بادشاہت رحمٰن ہى كى ہوگى۔ (الفرقان: ۲۶)، اور رحمان كیلئے تمام آوازیں پست ہوجائیں گى۔(طہ : ۱۰۸)، اور اس جیسى دیگر آیات جن میں رحمان کا ذكر اسى معنى میں آیا ہے۔ (السعدی: ۶۹۷)\nاس ہولناک صورتِ حال میں دیگر اسماء كو چھوڑ كر بطور خاص رحمان كا ذكر كیوں آیا ہے؟\nwords\nفَلاَ صَرِيخَپس كوئي مدد گار نه هوگا.\nيَخِصِّمُونَوه امور زندگي ميں جھگڑا كرتے هيں.\nالأَجدَاثِقبور.\nيَنسِلُونَوه جلدي سے نكليں گے.\nمَرقَدِنَاهماري قبريں."],[444,"§يس\ndeeds\nآپ یہ برابر پڑھتے رہئے: “اَللّٰهُمَّ اِنِّيْ أَسْأَلُكَ نَعِيْمًا لَا يَنْفَد”اےالله میں تجھ سے ایسى نعمت كا سوال كرتاہوں جو ختم نہ ہو.\nاپنے اعضاء و جوارح سے نیک عمل انجام دیجیئے جیسے: كسى مسلمان بھائى كا تعاون کرنا، راستے سے تكلیف ده چیز ہٹانا، نماز كیلئے چل كر جانا یا اس جیسے دیگر اعمال.\nآپ دعا کیجئے: “اَللّٰهُمَّ اِنِّيْ اَعُوْذُبِكَ أَنْ أُرَدَّ اِلىٰ أَرْزَلِ الْعُمَرِ، أَوْ أَنْ يَّتَخَبَّطَنِىَ الشَّيْطَانُ عِنْدَ الْمَوتِ” اے اللہ! میں تیری پناہ چاہتا ہوں اس بات سے کہ مجھے عمر کے ناکارہ ترین حصے کی طرف لوٹا دیا جائے اور اس سے کہ موت کے وقت شیطان مجھے خبطی و دیوانہ بنا دے.\nguid\nاہل جنت دنیا میں اطاعت میں مشغول رہنے کے بدلے جنت کے نعمتوں سے لطف اندوز ہونے میں منہمک رہیں گے.\nكتاب الٰہى كى آیتیں ترتیل سے پڑھئے اور اس میں غوروفکر کیجئے، کیونکہ اسى میں دلوں كى زندگى ہے.\nشعرو شاعرى جیسے ترانہ گانا وغیرہ میں اتنا مشغول مت ہوجائیے كہ یہ آپ كو قرآن كریم سے غافل كردے.\nrefl\nإِنَّ أَصۡحَٰبَ ٱلۡجَنَّةِ ٱلۡيَوۡمَ فِي شُغُلٖ فَٰكِهُونَ ٥٥\n(یعنی فرشتے یہ باتیں جہنمیوں سے مخاطب ہوکر کہیں گے تاکہ ان میں مزید حزن و ملال پیدا ہو اس مقام پر اہل جنت حاضر نہیں ہوں گے)۔ (ابن عاشور: ۲۳؍۴۱)\nالله تعالىٰ اہل جنت كى تكریم یوں كرےگا كہ انہیں جلد ہى جنت میں داخل كردےگا، اس بات پر آیت كریمہ كیسے دلالت كرتى ہے؟ بتائیے.\nوَٱمۡتَٰزُواْ ٱلۡيَوۡمَ أَيُّهَا ٱلۡمُجۡرِمُونَ ٥٩\nمقاتل كہتےہیں: آج كے دن تم نیکوکاروں سے الگ تھلگ ہوجاؤ۔ ضحاك كا قول ہے: جہنم میں ہر كافر كا ایك الگ گھر ہوگا، جس میں جہنمى داخل ہوگا اور پھر اسكے دروازے كو آگ سے بھر دیا جائےگا اور اس میں وه ہمیشہ كیلئے پڑا رہےگا۔ (البغوى: ۳؍۶۴۵)\nقیامت كے روز مجرمین اہل ایمان سے کیسے الگ تھلگ ہوں گے؟\n۞أَلَمۡ أَعۡهَدۡ إِلَيۡكُمۡ يَٰبَنِيٓ ءَادَمَ أَن لَّا تَعۡبُدُواْ ٱلشَّيۡطَٰنَۖ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ ٦٠\nاس جھڑكى میں كفر ومعصیت كى تمام قسموں کی جھڑکیاں بھی شامل ہیں ۔ اس لئے کہ یہ سب شیطان كى فرمانبردارى اور اس کی عبادت ہے۔ (السعدى: ۶۹۸)\nآیت كریمہ كى اس مذكوره جھڑكى میں كون لوگ شامل ہیں؟\nٱلۡيَوۡمَ نَخۡتِمُ عَلَىٰٓ أَفۡوَٰهِهِمۡ وَتُكَلِّمُنَآ أَيۡدِيهِمۡ وَتَشۡهَدُ أَرۡجُلُهُم بِمَا كَانُواْ يَكۡسِبُونَ ٦٥\nہاتھ کےكلام اورپیر کی شہادت كى تفریق بتاتےہوئے كہاگیا ہے كہ چونكہ ہاتھ بلاواسطہ کام انجام دے رہاتھا جبكہ پاؤں اس وقت حاضر تھا، اور حاضر وموجود كا قول دوسروں كیلئے شہادت وگواہى ہے۔ اسى طرح فاعل كا قول اپنے اوپر اپنے كئے یا كہے كا اقرار ہے، اسى لئے ہاتھوں سے جوچیز صادر ہوئى اس كى تعبیر ‘‘قول’’ سے كى گئى، اور پاؤں سے جو چیز صادر ہوئى اسے شہادت سے تعبیر کی گئی۔ (القرطبى: ۱۷؍۴۷۶)\nہاتھ كے حق میں كلام كى تعبیر اور پاؤں كے حق میں شہادت كى تعبیر کا كیا راز ہے؟\nوَمَن نُّعَمِّرۡهُ نُنَكِّسۡهُ فِي ٱلۡخَلۡقِۚ\nالله تعالىٰ ابن آدم كےبارے میں بتارہا ہے كہ جیسے جیسے اسكى عمر بڑھتى ہے وه قوت كے بعد كمزورى كى طرف پلٹا دیا جاتا ہے اور نشاط كے بعد معذوری اور بےبسی کی طرف ۔ اس سے یہ بتانا مقصود ہے کہ یہ دنیا فنا ہونے والی اور ادلا بدلى كى جگہ ہے، دوام اور ٹھہراؤ کی جگہ نہیں ہے۔ (ابن كثیر: ۳؍۵۵۵)\nبڑھاپے كے وقت انسان كى عمر پلٹ دینے كى خبر دینے سے كیا مراد ہے؟\nوَمَا عَلَّمۡنَٰهُ ٱلشِّعۡرَ وَمَا يَنۢبَغِي لَهُۥٓۚ إِنۡ هُوَ إِلَّا ذِكۡرٞ وَقُرۡءَانٞ مُّبِينٞ ٦٩\nابن قاسم نے مالك سے روایت كیا ہے كہ ان سے اشعار پڑھنے كے بارے میں سوال كیا گیا تو انہوں نے كہا:ہرگز كثرت سے شعر وشاعری نہ کرو كیونكہ الله تعالىٰ نے اس كا عیب بیان كرتےہوئے فرمایا: (وما علمناه الشعر وما ينبغي له)\"(القرطبى: ۱۷؍۴۸۴)\nكیا كثرت سے شعر پڑھنا قابل تعریف ہے؟ نیز اسكى دلیل كیا ہے؟\nلِّيُنذِرَ مَن كَانَ حَيّٗا وَيَحِقَّ ٱلۡقَوۡلُ عَلَى ٱلۡكَٰفِرِينَ ٧٠\nتاكہ قرآن ہر اس شخص كو آگاه كرے جو زنده ہےیعنی زندہ دل والے مومن کو، كیونكہ كافر تو مردے كى مانند ہے وه غور وفكر كرتا ہى نہیں ہے۔ (البغوى: ۳؍۶۴۹)\nاس آیت میں زندے اور مردے سے كیا مقصود ہے؟\nwords\nالأَرَائِكِمزين چارپائياں.\nوَامتَازُواعليحده هو جاؤ.\nلَمَسَخنَاهُمهم ان كي تخليق كو بدل ديں.\nمَكَانَتِهِمان كي جگهوں پر.\nمُضِيًّاكه وه ان سے پهلے گزر جائيں.\nنُعَمِّرهُهم اس كي عمر كو طويل كرديں گے.\nنُنَكِّسهُ فِي الخَلقِهم اس كي ابتدائي حالت پر لوٹا ديں گے."],[445,"§يس\ndeeds\nسوارى ، كھانےپینے اور لباس کی نعمتوں پر الله كا شكر ادا كیجئے.\nآپ یہ دعا کریں: “اَللّٰهُمَّ لَا تَكِلْنِىْ اِلىٰ نَفْسِىْ طَرْفَةَ عَيْنٍ، وَلَا أَقَلَّ مِنْ ذٰلِكَ” اے اللہ تو پلک جھپکنے کے برابر یا اس سے کم لمحہ کے لئے بھی مجھے میرے نفس کے سپرد نہ کر.\nیہ دعا پڑھیں: “اَللّٰهُمَّ أَعِنِّىْ وَلَا تُعِنْ عَلَىَّ، وَانْصُرْنِىْ وَلَا تَنْصُرْ عَلَىَّ، وَاهْدِنِىْ وَيَسِّرِالْهُدٰى لِيْ”اے اللہ! تیری اطاعت کے لئے میری مدد فرما اور تیری بندگی سے مجھے روکنے والی چیزوں کی مدد نہ فرما، اور مجھے غلبہ عطا فرما اور مجھے مغلوب نہ کر اور مجھے ہدایت نصیب فرما اور ہدایت کی اتباع میرے لئے آسان کردے.\nguid\nاپنى تمام تر حاجتوں میں صرف الله سے التجا کیجئے.\nاپنى پیدائش كى ابتدا پر غور كیجئے تاكہ آپ اپنى اوقات سے آگاه رہیں.\nازراہ عناد اور ترک حق باہم لڑائی جھگڑا نہ کریں.\nrefl\nأَوَ لَمۡ يَرَوۡاْ أَنَّا خَلَقۡنَا لَهُم مِّمَّا عَمِلَتۡ أَيۡدِينَآ أَنۡعَٰمٗا فَهُمۡ لَهَا مَٰلِكُونَ ٧١\nیعنى وہ ان جانوروں پر قابض اور غالب ہیں ۔ یعنى چوپایوں كوایسا وحشى اور انسانوں سے بدكنے والا نہیں بنایا كہ وه ان جانوروں كو اپنے قابو میں نہ كرسكیں، بلكہ انہیں انسانوں کے تابع بنادیا ہے۔ (البغوى: ۳؍۶۴۹)\nانسانوں كو چوپایوں كا مالك بنانے اور انہیں انكے تابع كردینے میں انعام واحسان كى كیا صورت ہے؟\nوَلَهُمۡ فِيهَا مَنَٰفِعُ وَمَشَارِبُۚ أَفَلَا يَشۡكُرُونَ ٧٣\n(أفلا يشكرون) اس یاد دہانى اور انعام واحسان كى فرع ہےجو كہ تعجب اور استفہام كے طور پر وارد ہوا ہے كیونكہ انہوں نے الله كى مختلف نعمتوں پر برابرشكر بجا لانا چھوڑ ركھا ہے، لہٰذا مضارع كا صیغہ لایا گیا تاكہ تسلسل وتجدد كا فائده حاصل ہو، كیونكہ یہ نعمتیں ہر گھڑى ، لگاتار ایك كے بعد ایك آتی رہتی ہیں۔(ابن عاشور: ۲۳؍۶۹)\nیہ آیت کریمہ ہر گھڑی از سر نو اللہ کا شکر بجالانے کی اہمیت پر دلالت کرتی ہے وہ کیسے؟\nفَلَا يَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّا نَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ ٧٦\nہم جانتےہیں كہ یہ جو باتیں (تم شاعر ہو تم جو لائے ہو وہ شعر ہے) كہہ رہے ہیں اس كا سبب حسد ہے، حالانكہ انہیں اچھى طرح معلوم ہے كہ جو كچھ آپ ان كے پاس لائے ہیں وه نہ شعر ہے ، نہ ہى شعر جیسا ہے اور آپ جھوٹے بھى نہیں ہیں۔ آپ جس چیز كى طرف انہیں بلا رہے ہیں اس كى حقیقت سے یہ آگاه ہیں، اسے یہ چھپا رہے ہیں جس کا ہمیں بخوبی علم ہے نیز آپ کی دعوت کو ان کی زبان سے اعلانیہ طور پر انکار کرنے کا بھی ہمیں علم ہے۔(الطبری: ۲۰؍۵۵۳)\nاس آیت سے ایك داعى كو كیا فائده ملتاہے؟\nإِنَّا نَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ ٧٦\nیعنى ہم ان کے سارے احوال اور انكى تمام كیفیات سے واقف ہیں، اور ہم انہیں اس دن ان کے غلط بیانی کا بدلہ دینگے اور اسى كے مطابق ان كےساتھ برتاؤ كرینگے، جس دن وه اپنا كوئى بھى كام غائب نہیں پائیں گے، خواه عمل عظیم ہو یا حقیر، چھوٹا ہو یا بڑا، بلکہ ان کے سارے اعمال چاہے نئے ہوں یا پرانے سب ان پر پیش کئے جائیں گے۔ (ابن كثیر: ۳؍۵۵۸)\nالله نے اپنے بارے میں جو یہ خبر دى ہے كہ وه كافروں كى كھلى چھپى سب باتیں جانتا ہے تو اس سے كیا مراد ہے؟\nقُلۡ يُحۡيِيهَا ٱلَّذِيٓ أَنشَأَهَآ أَوَّلَ مَرَّةٖۖ وَهُوَ بِكُلِّ خَلۡقٍ عَلِيمٌ ٧٩\nاللہ تعالیٰ زمین کے تمام حصوں میں مدفون ہڈیوں کی حقیقت کو جانتا ہے کہ وہ کہاں گئی اور کہاں بوسیدہ و ریزہ ریزہ ہوکر بکھری پڑی ہے۔ (ابن كثیر: ۳؍۵۵۹)\nاس آیت كى روشنى میں الله عزوجل كے علم كى وسعت بیان كیجئے.\nٱلَّذِي جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلۡأَخۡضَرِ نَارٗا فَإِذَآ أَنتُم مِّنۡهُ تُوقِدُونَ ٨٠\nالله تعالىٰ نے یہاں دوباره زنده كئے جانے كى تیسرى دلیل ذكر كى ہے۔ (وہى ہے جس نے تمہارے لئے سبز درخت سے آگ پیدا كردى جس سے تم آگ سلگاتےہو) ۔ چنانچہ جس ذات نے خشک آگ کو ہرےبھرے ، سبز اور انتہائى گیلے درخت سے دونوں میں شدید تضاد كے باوجود نکالا ہے ٹھیک اسی طرح قبروں سے مردوں كو بھى نكالنے پر یقیناً وہ قادر ہے۔ (السعدى: ۷۰۰)\nاس آیت سے دوباره زنده كئے جانےپر كس طرح استدلال كیا گیاہے؟\nفَسُبۡحَٰنَ ٱلَّذِي بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءٖ وَإِلَيۡهِ تُرۡجَعُونَ ٨٣\nانہوں نے کماحقہ اللہ تعالیٰ کی قدر نہیں کی، اور جس نے بھى قیامت کے دن دوبارہ زندہ کئے جانے كا انكار كیا اس نے قدرت الٰہى سے جہالت كى بنیاد پرہی انكار كیا۔(ابن جزى: ۲؍۲۳۰)\nكافروں نے قیامت کے دن دوبارہ زندہ کئے جانے کا انكار كیوں كیا؟\nwords\nوَذَلَّلنَاهَاهم نے اس كو مسخر كرديا.\nرَكُوبُهُمجس پر وه سفر ميں سوار هوتے هيں.\nخَصِيمٌبهت زياده جھگڑا كرنے والا.\nرَمِيمٌبوسيده / بكھرے هوئے."],[446,"§الصافات\ndeeds\nستاروں كى تخلیق پرغور كیجئے، پھر اس پر الله كا شكر بجا لائیے كہ اس نے شیطانوں كو آسمان كى باتیں اچكنے سے روك ركھا ہے۔ تاكہ وه بندوں كو فتنے میں نہ مبتلا كرسكیں.\nشیطان مردود كے شر سے الله تعالىٰ كى پناه طلب كیجئے.\nآپ نے جو نصیحت سنی اسے یاد کریں اور اسے روبہ کار میں لانے میں سبقت کریں.\nguid\nشیاطین كى حالت اور نبى كریم صلی اللہ علیہ وسلم كى بعثت كے بعدا نہیں دھتكارے جانے پر اچھى طرح غور كیجئے.\nآپ ان لوگوں میں سے مت ہوجائیے كہ جنہیں نصیحت كى جاتى ہے اور وه مانتےنہیں.\nآپ اپنى زبان اور اپنے افعال كى حفاظت كیجئے، تاكہ آپ كواللہ کے سامنے ایسے موقف سے نہ گزرنا پڑے جو آپ كى رسوائی كا باعث بنے.\nrefl\nوَٱلصَّٰٓفَّٰتِ صَفّٗا ١\nجیسے لوگ نماز كیلئے دنیا میں صفیں لگاتےہیں اسى طرح فرشتے آسمان میں بھى صف لگاتےہیں۔ اور یہ بھی كہاگیا ہےكہ فرشتے ہوا میں پرپھیلائے صف باندھےٹھہرے رہتےہیں حتی كہ الله تعالىٰ جو چاہتا ہے اس كا انہیں حكم دے دے ، یعنى حكم الٰہى كے انتظار میں صف بستہ كھڑے رہتے ہیں۔ (القرطبى: ۱۸؍۶)\nالله كى عبادت اور خاكسارى میں فرشتوں كا حال بتائیے.\nإِنَّ إِلَٰهَكُمۡ لَوَٰحِدٞ ٤ رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَرَبُّ ٱلۡمَشَٰرِقِ ٥\nیعنى ان سارى مخلوقات كا وہى پیدا كرنے والا ہے، وہى روزى دینے والا ہے اور وہى تدبیر كرنے والا ہے۔ پس جس طرح مخلوقات کی پرورش و پرداخت(ربوبیت) میں اسكا كوئى شریك نہیں اسى طرح اسكى الوہیت میں بھى اسكا كوئى ساجھى دار نہیں ہے۔ اكثر الله تعالىٰ توحید ربوبیت كے ذریعے توحید الوہیت ثابت كرتا ہے كیونكہ ربوبیت الوہیت كى دلیل ہے۔ اور عبادت میں شرک کرنے والے(مشرکین) بھى اس كا اقرار كرتےتھے، چنانچہ مشرکین کے ربوبیت کے اقرار کی بنا پر ان کے انکار کئے ہوئے الوہیت کا اقرار کرنا ان پر واجب ہوجاتا ہے۔ (السعدى: ۷۰۰)\nالله نے توحید الوہیت كے بعد توحید ربوبیت كا ذكر كیوں كیا ہے؟\nإِنَّا زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِزِينَةٍ ٱلۡكَوَاكِبِ ٦\nالله تعالىٰ نے بطور خاص آسمان دنیا كا ذكر اس لئے كیا ہے كیونكہ ہم اسے اپنى آنكھوں سے بلاواسطہ دیكھتےہیں، اور اس لئے بھى كہ شیطان سے حفاظت صرف اسى آسمان كى ہوتى ہے۔ (ابن عطیہ : ۴؍۴۶۶)\nبالخصوص آسمان دنیا كا ذكردو اسباب کی وجہ سے آیا ہے، وہ دو اسباب کیا ہیں.\nبَلۡ عَجِبۡتَ وَيَسۡخَرُونَ ١٢\nقتادہ فرماتے ہیں کہ یہ قرآن جب نازل ہوا تو رسول الله صلی اللہ علیہ وسلم كوقرآن کریم کی موجودگی اور بنو آدم كى گمراہى کے اکٹھا ہونے پر تعجب ہوا ۔ كیونكہ آپ صلی اللہ علیہ وسلم سمجھتے تھے كہ جو بھى قرآن سنےگا اس پر وه ایمان لے آئےگا ، لیکن جب مشركین نے قرآن سنا تو انہوں نے اس کا مذاق اڑایا اور ایمان نہیں لائے، چنانچہ آپ صلی اللہ علیہ وسلم كو اس پر بہت تعجب ہوا۔ (البغوى: ۳؍۶۵۶)\nمشرکین کا قرآن پر ایمان نہ لانے کی وجہ نبی کریم صلی اللہ علیہ وسلم کو تعجب کیوں ہوا؟\nقُلۡ نَعَمۡ وَأَنتُمۡ دَٰخِرُونَ ١٨\nیعنی تم ذلیل اور رسوا ہوگے، كیونكہ جس چیز كا وه انكار كرتےتھے جب اسے اپنى آنكھوں سے دیكھ لیں گے تو لا محالہ رسوا ہوں گے۔ (القرطبى: ۱۸؍۲۲۰)\nقیامت كے دن نافرمانوں كى ذلت ورسوائى كا سبب كیا ہوگا؟\n۞ٱحۡشُرُواْ ٱلَّذِينَ ظَلَمُواْ وَأَزۡوَٰجَهُمۡ وَمَا كَانُواْ يَعۡبُدُونَ ٢٢ مِن دُونِ ٱللَّهِ فَٱهۡدُوهُمۡ إِلَىٰ صِرَٰطِ ٱلۡجَحِيمِ ٢٣\nحساب وكتاب اورجزا وسزا كیلئے انہیں جمع كرو، انكے ہمنواؤں ، انكے متبعین اور ان جیسے لوگوں كو بھى اكٹھا كرو۔ قتاده اور كلبى كا قول ہے کہ: ہر وه شخص جو انكى طرح عمل كرتا تھا، چنانچہ شرابى شرابیوں كے ساتھ ہوگا، اور زانى زانیوں كے ساتھ۔ (البغوى: ۳؍۶۵۷)\nقیامت كے دن آدمى كا حشر كس كے ساتھ ہوگا اور ہمیں اس سے کیا سبق ملتا ہے؟\nوَقِفُوهُمۡۖ إِنَّهُم مَّسۡـُٔولُونَ ٢٤\nجب جہنم كى طرف لے جایا جائےگا تو انہیں پل صراط پر روك کر یہ كہا جائے گا كہ انہیں روكو ان سے كچھ ضرورى سوال كرنا ہے ۔ ابن عباس رضی اللہ عنہما كہتےہیں كہ ان كى تمام باتوں اور تمام كاموں كے بارے میں پوچھا جائےگا۔ (البغوى: ۳؍۶۵۷)\nالله تعالىٰ كے حضور لوگوں كو كہاں ٹھہرایا جائےگا، اور قیامت كے دن كس بارے میں سوال ہوگا؟\nwords\nوَالصَّآفَّاتِفرشتوں كي قسم هے جب وه عبادت كے ليے صف بندي كرتے هيں.\nفَالزَّاجِرَاتِفرشتوں كي قسم جب وه بادلوں كو هانكتے هيں.\nفَالتَّالِيَاتِ ذِكرًافرشتوں كي قسم هے جب وه الله تعاليٰ كے ذكر كي تلاوت كرتے هيں.\nمَارِدٍسركشي جن / اطاعت سے نكلا هوا.\nدُحُورًاشياطين كو استماع سے رانده ء درگاه كيا هوا.\nوَاصِبٌهميشه تكليف دينے والي.\nخَطِفَ الخَطفَةَوه چوري كرتے هوئے كوئي كلمه اچك ليتے هيں.\nلاَزِبٍچپك جانے والي."],[447,"§الصافات\ndeeds\nالله کی رضا کیلئے اپنے كسى بھائى كى زیارت كیجئے.\nكسى داعى كے دفا ع میں كوئى پیغام تحریر كیجئے.\nآج زیاده سے زیاده “لَا اِلٰهَ اِلَّا اللّٰه”پڑھئے.\nguid\nنیك لوگوں كى صحبت لازم پكڑئیے ، اور ذلیل لوگوں سے كناره كش ہوجائیے.\nگمراه كن سرداروں اور انكى خواہشات سے بچئیے، یہ سب كے سب قیامت كےدن آپ کے دشمن بن جائیں گے.\nحق كیلئے تواضع اختیار كیجئے اس کی خاطر اپنا بازو پست ركھئے اور تكبر چھوڑ دیجئے.\nrefl\nمَا لَكُمۡ لَا تَنَاصَرُونَ ٢٥\nگویا كہ وه اس سوال كا جواب ہى نہ دے سكیں گے كیونكہ ذلت اور پستى ان پرچھائی ہوگى، وه نار جہنم كے سپردہوچكےہوں گے، خوفزده ہوں گے، پست و مایوس ہوچكے ہونگے، لہٰذا بول نہیں سكیں گے۔ (السعدى: ۷۰۲)\nالله نے جہنمیوں كے سوال کا تذكره كیا لیكن ان كا جواب ذكر نہیں كیا ، كیوں؟\nفَإِنَّهُمۡ يَوۡمَئِذٖ فِي ٱلۡعَذَابِ مُشۡتَرِكُونَ ٣٣ إِنَّا كَذَٰلِكَ نَفۡعَلُ بِٱلۡمُجۡرِمِينَ ٣٤\nہم ان كے ساتھ ایسے ہى كرتےہیں جنہوں نےدنیا میں الله كى اطاعت کے بجائے اسكى نافرمانى كا راستہ اپنایا تھا، اور ایمان كے بجائے كفر كیا تھا، لہذا ہم انہیں دردناك عذاب دینگے، نیز انہیں اور ان كے سب ساتھیوں كو جہنم میں اكٹھا كردینگے۔ (الطبرى: ۲۱؍۳۳)\nاس دنیا میں اشتراك ومشابہت آخرت میں بھی اشتراك ویکسانیت كا باعث ہے، بیان كیجئے كہ كیسے؟\nأُوْلَٰٓئِكَ لَهُمۡ رِزۡقٞ مَّعۡلُومٞ ٤١ فَوَٰكِهُ وَهُم مُّكۡرَمُونَ ٤٢ فِي جَنَّٰتِ ٱلنَّعِيمِ ٤٣ عَلَىٰ سُرُرٖ مُّتَقَٰبِلِينَ ٤٤ يُطَافُ عَلَيۡهِم بِكَأۡسٖ مِّن مَّعِينِۢ ٤٥ بَيۡضَآءَ لَذَّةٖ لِّلشَّٰرِبِينَ ٤٦ لَا فِيهَا غَوۡلٞ وَلَا هُمۡ عَنۡهَا يُنزَفُونَ ٤٧ وَعِندَهُمۡ قَٰصِرَٰتُ ٱلطَّرۡفِ عِينٞ ٤٨ كَأَنَّهُنَّ بَيۡضٞ مَّكۡنُونٞ ٤٩\nجنتیوں كے كھانے پینے ، ان كى مجلسوں كا ذكر اور دیگر نعمتوں كى تفصیلات ، الله كے اس قول: (في جنات النعيم) میں شامل ہے، لیكن پھر بھى ان چیزوں كى تفصیلات الگ سے اس لئے بیان كى گئى ہے تاكہ نفوس ان كى جانب مائل ہوں اور انكے حصول كى رغبت بڑھے۔ (السعدى: ۷۰۳)\nجنت كى نعمتیں تفصیل سے كیوں بیان كى گئى ہیں حالانكہ الله كا قول (في جنات النعيم) ان سب كو شامل ہے؟\nفَوَٰكِهُ وَهُم مُّكۡرَمُونَ ٤٢ فِي جَنَّٰتِ ٱلنَّعِيمِ ٤٣\nالله كى جانب سے انكى تكریم كى جائےگى، انكے درجات بلند كئے جائیں گے، الله كى بات سنیں گے ، اور اس سے ملاقات كا شرف پائیں گے۔ (القرطبى: ۱۸؍۲۹)\nالله تعالىٰ اہل جنت كو جو اعزاز بخشے گا اس میں سے كچھ بیان كیجئے.\nلَا فِيهَا غَوۡلٞ وَلَا هُمۡ عَنۡهَا يُنزَفُونَ ٤٧\nنہ وه بہكیں گے اور نہ ہى كسى بیمارى یا دردسر میں مبتلا ہوں گے، بلكہ بدمستى اور نشے والى كیفیت الله ان سے دور كردےگا تاكہ نعمتوں سے بھرپور لطف اندوز ہوسكیں۔ (القرطبى: ۱۸؍۳۱-۳۲)\nالله اہل جنت سے نشہ كیوں دور کر دےگا؟\nوَعِندَهُمۡ قَٰصِرَٰتُ ٱلطَّرۡفِ عِينٞ ٤٨\nیعنى كمال پاكدامنى كیوجہ سے انكى نظریں اپنے شوہر تك ہى محدود ہوں گى، كسى اور كى جانب تجاوز نہیں كرینگى، اور اپنے شوہر كےجمال وكمال كیوجہ سے كسى اور كى طلب وچاہت دل میں آئے گى ہى نہیں۔ یہ جنت میں مردوں كے مکمل حسن كى دلیل ہے۔ (السعدى: ۷۰۳)\nآیت كریمہ جنت میں مردوں كے بے پناه حسن پر كیسے دلالت كرتى ہے؟\nفَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَسَآءَلُونَ ٥٠ قَالَ قَآئِلٞ مِّنۡهُمۡ إِنِّي كَانَ لِي قَرِينٞ ٥١\nیہ بات معلوم ہے کہ اہل علم كو علم كےبارےمیں باہم سوال كرنے اور اسكى جستجو سے جو لذت حاصل ہوتى ہے،وہ اس سے كہیں زیاده ہے جو دنیاوى گفتگو سے ملتى ہے ۔ چنانچہ انہیں لذت كى اس قسم كا بھى ایك بڑا حصہ میسر آئےگا اور جنت میں ان کےسامنے ایسے علمى حقائق كے انكشاف ہوں گے جو ناقابل بیان ہے۔(السعدى: ۷۰۴)\nاہل جنت كو جنت میں انكى گفتگو سے ایك خاص قسم كى نعمت حاصل ہوگى ، وه كیا ہے، بتائیے.\nwords\nعَنِ اليَمِينِحق اور دين كي جانب سے.\nسُلطَانٍحجت اور قوت.\nطَاغِينَنافرماني ميں حد سے تجاوز كرنے والے.\nفَحَقَّ عَلَينَاهم پر واجب هوگيا.\nالمُخلَصِينَجو خالص الله تعاليٰ كي عبادت كرتے هيں.\nلاَ فِيهَا غَولٌاس ميں كوئي ايسي چيز نهيں هوگي جو ان كي عقول كو اچك لے.\nوَلاَ هُم عَنهَا يُنزَفُونَنه هي وه نشه ء پاتے هيں؛ اور نه هي ان كے بدنوں كو تكليف هوتي هے.\nمَكنُونٌايسا محفوظ جس كو كسي هاتھ نے نه چھوا هو.\nقَرِينٌساتھي۔ ساتھ رهنے والا."],[448,"§الصافات\ndeeds\nآج اپنى والده كا ان كے كاموں میں ہاتھ بٹائیے.\nالله کی قربت حاصل كرنے كیلئے كسى دن روزه ركھئے تاكہ قیامت كے دن كى گرمى سے نجات پاسكیں.\nالله پاك سے دعا كیجئے، اسے پكارئیے اور اس سے آه وزارى کیجئے.\nguid\nایك نیک دوست دسیوں غافل لوگوں سے بہتر ہے.\nظلم كسى پر بھى مت كیجئے، کیونکہ(زقوم) تھوہڑ كا جھاڑ ظالموں كا عذاب ہے.\nیاد ركھئے ! الله كے سوا اور كوئى پكار كا نہ جواب دینے والا ہے اور نہ ہى مدد كرنے والا ہے.\nrefl\nفَٱطَّلَعَ فَرَءَاهُ فِي سَوَآءِ ٱلۡجَحِيمِ ٥٥ قَالَ تَٱللَّهِ إِن كِدتَّ لَتُرۡدِينِ ٥٦ وَلَوۡلَا نِعۡمَةُ رَبِّي لَكُنتُ مِنَ ٱلۡمُحۡضَرِينَ ٥٧\nاس آیت میں یہ عبرت ہے كہ برے دوستوں سے احتراز كرنا چاہئیے ، لازمی طور پر ان چیزوں سے جنكى طرف یہ بلا رہے ہیں اور ان تباه کن چیزوں سے بچنا چاہئے جسے یہ مزین كركے پیش كرتےہیں۔\nآیت كریمہ كى روشنى میں برے ساتھى كى خطرناكى بیان كیجئے.\nفَٱطَّلَعَ فَرَءَاهُ فِي سَوَآءِ ٱلۡجَحِيمِ ٥٥\nبعض علماء كہتےہیں كہ اگر الله عز وجل تعارف نہ کراتا تو پہچان بھى نہ پاتے، كیونكہ آدمى كا رنگ اور اسكى ہیئت تبدیل ہوچكى ہوگى۔ (القرطبى: ۱۸؍۳۹)\nساتھى اپنے جہنمى دوست كو كیسے پہچانےگا حالانكہ اس كا رنگ اور اسكى ہیئت تو بدل چكى ہوگى؟\nوَلَوۡلَا نِعۡمَةُ رَبِّي لَكُنتُ مِنَ ٱلۡمُحۡضَرِينَ ٥٧\nاگر میرے رب كى نعمت نہ ہوتى ، اسلام كے ذریعے مجھےاپنى رحمت وانعام سے سرفراز نہ فرماتا تو میں بھى تمہارے ساتھ جہنم میں حاضر كیا جاتا ۔(البغوى: ۳؍۶۶۱)\nكیا مومن کو جہنم اور اسكى دہكتى آگ سے نجات صرف اسكے عمل اور اطاعت سے مل جائےگى؟\nإِنَّهَا شَجَرَةٞ تَخۡرُجُ فِيٓ أَصۡلِ ٱلۡجَحِيمِ ٦٤\nیہ اس درخت (زقوم) كے نكلنے کی جگہ اور اسكى جڑ ہے جو كہ انتہائى برى ہے۔ اور اگر اگنے كى جگہ ہی برى ہے تو یہ اس بات كى دلیل ہے کہ وہاں سے اگنے والى شیء بھى انتہائی گھٹیا اور برى ہوگی۔ اسى لئے الله تعالىٰ نے اس كے اگنے كى جگہ اور اس كے پھل كى صفت ذكر کرکے ہمیں اس كے شر سے آگاه كیا ۔(السعدى: ۷۰۴)\nاس درخت كےبارے میں یہ كہنا كہ یہ جہنم كى جڑ سے اگے گا سے كیا فائده ہے؟\nطَلۡعُهَا كَأَنَّهُۥ رُءُوسُ ٱلشَّيَٰطِينِ ٦٥\nیہ اسكى قباحت وكراہت كا ذكر ہے، اور اسكى تشبیہ شیطان كے سر سے دى گئى ہے گرچہ شیطان كا سر مخاطب کے یہاں معروف نہیں ہے۔ وہ اس لئے کہ لوگوں كے دلوں میں شیطان كى قبیح صورت کا تصور پیوست ہے۔ (ابن كثیر: ۴؍۱۲)\nایك غیر معروف چیز یعنى شیطان كے سر سے زقوم درخت كے خوشے كى تشبیہ كیوں دى گئى ہے؟\nثُمَّ إِنَّ مَرۡجِعَهُمۡ لَإِلَى ٱلۡجَحِيمِ ٦٨ إِنَّهُمۡ أَلۡفَوۡاْ ءَابَآءَهُمۡ ضَآلِّينَ ٦٩\nگویا كہ پوچھا جائے گا كہ اس ٹھكانے تك انہیں كس نے پہونچایا ؟ تو جواب ہوگا: انہوں نے یقیناً اپنےآباء و اجداد كو گمراه پایا تھا۔(السعدى: ۷۰۴)\nان دونوں مسلسل آیتوں كےبیچ كیا تعلق ہے؟\nوَلَقَدۡ ضَلَّ قَبۡلَهُمۡ أَكۡثَرُ ٱلۡأَوَّلِينَ ٧١\nان سے پہلے جو لوگ گمراه ہوئے ان كى صفت الله نے (أكثر الأولين) (اگلے لوگوں کی اکثریت) سے اس لئے بیان فرمائى ہے تاكہ كمزور عقل والے مشركین كى كثرت سے دھوكہ نہ كھائیں اور اسے فخر کی دلیل نہ بنائیں اور اس لئے بھی کہ یہ لوگ اچھى طرح سے جان لیں كہ عدد كى كثرت گمراہوں كى گمراہى ، یا خطاكاروں كى خطا كا جواز نہیں بن سکتی۔ اب دونوں میں سے كسى ایك كى تعداد كم یا زیاده ہوجائےتو كوتاه نظروں اور كم عقلوں كو كسى فتنے میں نہیں پڑنا چاہیئے۔الله تعالىٰ كا ارشاد ہے: آپ فرمادیجئے: ناپاك اور پاك برابر نہیں ، اگرچہ آپ كو ناپاك كى كثرت بھلی ہی کیوں نہ لگے۔ (المائده: ۱۰۰)۔ (ابن عاشور: ۲۳؍۱۲۸)\nكثر ت و قلت ہدایت و گمراہى كى دلیل نہیں ہیں، اسے بیان كیجئے.\nwords\nلَمَدِينُونَهم ضرور حساب كئے جانے والے هيں.\nإِن كِدتَبے شك آپ قريب هيں.\nلَتُردِينِيعني تم اپني گمراهيوں كي وجه سے مجھے هلاك كروگے.\nالمُحضَرِينَجو عذاب ميں آپ كے ساتھ حاضر هوں گے.\nطَلعُهَااس كے پھل.\nلَشَوبًاملاهوا؛ ممزج.\nأَلفَواانهوں نے پايا.\nيُهرَعُونَوه گمراهي كي اتباع ميں جلدي كرتے هيں."],[449,"§الصافات\ndeeds\nشہوات وشبہات كى بیماریوں سے الله کی پناه طلب كیجئے.\nیہ دعا پڑھئے: “اَللّٰهُمَّ ارْزُقْنِىْ ذُرِّيَّةً طَيِّبَةً، إِنَّكَ سَمِيْعُ الدُّعَاءِ” اے اللہ تو مجھے نیک اولاد عطا فرما بلاشبہ تو دعاؤں کو سننے والا ہے.\nاپنے والد محترم كاتعاون كیجئے اور جس قدر جلد ممكن ہو ان كى مانگیں پورى كیجئے.\nguid\nاحسان کے ساتھ اپنے رب کی عبادت کرکے اور لوگوں پر احسان کرکے احسان کرنے والوں میں شمار ہوجائیے.\nہر غلاظت سے اپنا دل پاك ركھئے، اور اللہ سے دل كى سلامتى كى دعا مانگتے رہئے.\nجب برائى دیكھئے تو حكمت كےساتھ اس پر نكیر كیجئے، گرچہ برائی میں ملوث شخص اپنا كوئى انتہائى قریبى ہى كیوں نہ ہو، جیسے باپ وغیره.\nrefl\nإِذۡ جَآءَ رَبَّهُۥ بِقَلۡبٖ سَلِيمٍ ٨٤\nیعنى شرك وشك سے پاک دل ۔ عوف الاعرابى كا كہنا ہے كہ میں نے محمد بن سیرین سے پوچھا كہ بے عیب دل كیا ہے؟ تو انہوں نے جواب دیا: الله کے واسطے مخلوق كى خیرخواہى كرنے والا۔ (القرطبى: ۱۸؍۵۰)\nبے عیب دل كى وہ صفات كیا ہیں جن سے ہمیں اپنے دلوں کو متصف كرنا چاہئے؟\nفَمَا ظَنُّكُم بِرَبِّ ٱلۡعَٰلَمِينَ ٨٧\nالله رب العالمین کا تمہارے ساتھ کس برتاؤ کی تمہیں توقع ہے حالانكہ تم نے اس كے ساتھ غیروں كى عبادت كى ہے، یہ انكے شرك پر قائم رہنے پر سخت سزا كى دھمكى ہے۔ (السعدى : ۷۰۵)\nآیت میں مشركین كو ڈرایا اور خوف دلایا گیا ہے، اسكى وجہ بیان كیجئے.\nفَرَاغَ إِلَىٰٓ ءَالِهَتِهِمۡ فَقَالَ أَلَا تَأۡكُلُونَ ٩١\nابراہیم علیہ السلام نے یہ بات ان بتوں کے پجاریوں كا مذاق اڑاتے ہوئے كہى تھى ۔ (ابن جزى: ۲؍۲۳۸)\nابراہیم علیہ السلام نے بتوں كو كیسے مخاطب كیا حالانكہ وه تو كچھ بھى نہیں سمجھتے بوجھتے ہیں؟\nوَقَالَ إِنِّي ذَاهِبٌ إِلَىٰ رَبِّي سَيَهۡدِينِ ٩٩\nیہ آیت علیحدگی اختیار کرنے اور ہجرت كرنے كى دلیل ہے اوراس كام کو سب سے پہلے ابراہیم علیہ السلام نے اس وقت انجام دیا جب الله نے انہیں نار نمرود سے نجات د ى تھى، انہوں نے كہا: (إني ذاهب إلى ربي) یعنى اپنى جائے پیدائش اور اپنى قوم كا شہر چھوڑ كر ایسی جگہ جارہاہوں، جہاں میں اپنے رب كى عبادت كرسكوں۔ (القرطبى: ۱۸؍۵۹)\nمومن كیلئے دورى اور ہجرت كب مشر وع ہے؟\nرَبِّ هَبۡ لِي مِنَ ٱلصَّٰلِحِينَ ١٠٠\nابراہیم علیہ السلام نے اللہ تعالیٰ سے نیک اور صالح اولاد مانگی كیونكہ اولاد كى نعمت تب مكمل ہوتی ہے جب وه صالح وپرہیزگار ہو۔ بیٹوں كى صالحیت باپوں كى آنكھوں كى ٹھنڈك ہے ، اور اولاد کی پرہیزگاری وصالحیت میں سے یہ ہےكہ وه اپنے والدین كے فرمانبردار ہوں۔ (ابن عاشور: ۲۳؍۱۴۸)\nنیك اولاد كیلئے دعاء كى اہمیت بیان كیجئے.\nفَلَمَّا بَلَغَ مَعَهُ ٱلسَّعۡيَ قَالَ يَٰبُنَيَّ إِنِّيٓ أَرَىٰ فِي ٱلۡمَنَامِ أَنِّيٓ أَذۡبَحُكَ فَٱنظُرۡ مَاذَا تَرَىٰۚ قَالَ يَٰٓأَبَتِ ٱفۡعَلۡ مَا تُؤۡمَرُۖ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ ١٠٢\nاگر یہ كہا جائے كہ الله كى جانب سے ایك حتمى معاملہ میں انہوں نے مشوره كیوں كیا؟ تو جواب یہ ہوگا كہ انہوں نے مشوره اس لئے نہیں كیا تھا كہ اپنى رائےسے پلٹ جائیں بلكہ بیٹے كى بات یقینى طور سے جاننا چاہتے تھے تاكہ اس كا دل مضبوط ہوجائے، اور یہ اسكے لئے صبر كى تمہید بن جائے چنانچہ بیٹے نے بہترین جواب دیا۔ (ابن جزى: ۲؍۲۳۸)\nابراہیم علیہ السلام اپنے بیٹے سے مشوره كیوں كیا جبكہ انبیاء كا خواب سچا ہوتاہے؟\nسَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ ١٠٢\nبیٹے نے باپ كو بتایا كہ صبر كیلئے وه پورے طور پر تیار ہے اور اسے الله كى مشیئت سے اس لئے جوڑدیا كیونكہ اس كى مرضى كے بغیر كچھ نہیں ہوتا ہے۔ (السعدى: ۷۰۶)\nاسماعیل علیہ السلام نے اپنے صبر كو الله تعالىٰ كى مشیئت سے جوڑا ، اسكا كیا فائده ہے؟\nwords\nوَتَرَكنَا عَلَيهِاور هم نے اس ذكر جميل پر باقي ركھا.\nفِي الآخِرِينَان لوگوں ميں جو ان كے بعد آئے.\nشِيعَتِهِاس كے دين و منهج كي اتباع كرنے والے.\nأَئِفكًا آلِهَةًكيا تم عبادت كے ليے كوئي دوسرا من گھڑت خدا چاهتے هو.\nفَنَظَرَاس نے سوچتے هوئے نظر ستاروں كي طرف اٹھائي.\nسَقِيمٌبيمار هوں ۔ يه تعريض هے۔ مراد ميں كمزور هوں.\nيَزِفُّونَوه جلدي سے غصه ميں آگے بڑھ جاتے هيں."],[450,"§الصافات\ndeeds\nاپنے بھائى كے روبرو مسكرائیے، خنده پیشانى سے پیش آئیے، اپنے پڑوسى كى مدد كیجئے، اس كا بوجھ اٹھالیجئے، یا اپنے ساتھیوں سے اچھى بات كیجئے یہ سب احسان ہے.\nآپ یہ دعا کریں: “اَللّٰهُمَّ اهْدِنِىْ الصِّرَاطَ الْمُسْتَقِيْم” اے اللہ! تو مجھے صراط مستقیم اپنانے کی توفیق عطا فرما.\nاپنے ساتھیوں یا اپنے محلے میں كوئى كیسٹ یا كوئى كتابچہ تقسیم کرکے انہیں الله كى طرف دعوت دیجئے.\nguid\nحسب نسب اور جاه ومنصب آدمى كو نجات نہیں دلا سكتے، بلکہ الله ارحم الراحمین كى رحمت كے بعد نجات كا دار ومدار نیك اعمال پر ہے.\nاچھى طرح ذہن نشین كرلیجئے كہ تنگى اور سختى كے بعد كشادگى آتى ہے، لہذا مایوس نہ ہوں ، بلاشبہ اگر كوئى الله كى خاطر كچھ چھوڑتا ہے تو الله اس كے بدلے میں اس سے بہتر چیز عطا كردیتا ہے.\nغیر الله كو پكارنا تقوىٰ كے منافى عمل ہے، لہٰذا تقویٰ حاصل كرنےكیلئے صرف اور صرف الله كو پكارئیے.\nrefl\nفَلَمَّآ أَسۡلَمَا وَتَلَّهُۥ لِلۡجَبِينِ ١٠٣\nاللہ کی اطاعت اور اس کےحکم کی تعمیل کی خاطر وہ دونوں مطیع ہوگئے، ابن عباس رضی اللہ عنہما كا قول ہے کہ حضرت ابراہیم نے اسماعیل کوزمین پر پیشانی کے بل لٹادیا ، اور پیشانی كےبیچ والے حصے کو جبہہ کہا جاتا ہے۔ (البغوى: ۳؍۶۶۷)\nفرمان الٰہی (أسلما)میں تثنیہ كے صیغے سے تعبیر كا فائده ؟\nقَدۡ صَدَّقۡتَ ٱلرُّءۡيَآۚ\nیعنى سچی نیت سے زمین پر ذبح كیلئے بیٹے کو لٹا دینے ہى سے تمہارے خواب كا مقصود حاصل ہوگیا۔ (ابن كثیر: ۴؍۱۷)\nابراہیم علیہ السلام نے خواب كیسے سچ كر دكھایا حالانكہ بیٹے كو انہوں نے ذبح بھى نہیں كیا؟\nإِنَّ هَٰذَا لَهُوَ ٱلۡبَلَٰٓؤُاْ ٱلۡمُبِينُ ١٠٦\nوه رحمٰن كے خلیل ہیں ، اور خلت محبت كى سب سے اعلى قسم ہے، یہ ایسا منصب ہے جو كہ شركت قبول نہیں كرتا بلكہ تقاضہ كرتا ہے كہ دل كے تمام اجزاء محبوب سے منسلك ہوں ، چنانچہ جب دل كا ایك حصہ اپنے بیٹے اسماعیل علیہ السلام سے جڑا تو الله نے خلیل كى محبت بے لوث کرکے دوستی کا امتحان لینا چاہا۔ لہذا الله نے اسى كے ذبح كا حكم دیدیا جسكى محبت رب كى محبت سے ٹكرا سکتى تھى اور كسى قدر آڑے آسکتى تھى ۔ چنانچہ جب ابراہیم علیہ السلام نے الله كى محبت كو مقدم كیا ، اپنى خواہش پر اسے ترجیح دى اور بیٹے كى قربانى كا پختہ اراده كرلیا اور دل سے وه چیز زائل ہوگئى جو حب الہى میں حائل بن سكتى تھى لہذا اب ایسى صورت میں ذبح كا كوئى خاص فائده نہیں رہا۔ (السعدى: ۷۰۶)\nذبح كا یہ واقعہ امتحان بھى تها اور ابراہیم علیہ السلام كے دل كى صفائى کا سامان بهى، كیسے؟\nوَفَدَيۡنَٰهُ بِذِبۡحٍ عَظِيمٖ ١٠٧\nیہ اس ناحیہ سے عظیم تھا كیونكہ اسماعیل علیہ السلام كى قربانى كا فدیہ تھا، عظیم ترین عبادت تھى، اور قیامت تك كیلئے یہ قربانى سنت ابراہیمى كا درجہ پانے والى تھى۔ (السعدى: ۷۰۶)\nاس قربانى كو عظیم كى صفت سے متصف كرنے كى وجہ كیا ہے؟\nوَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ ١٠٨ سَلَٰمٌ عَلَىٰٓ إِبۡرَٰهِيمَ ١٠٩\nابراہیم علیہ السلام نے الله سے سوال كرتےہوئےكہا: ﴿وَٱجۡعَل لِّي لِسَانَ صِدۡقٖ فِي ٱلۡأٓخِرِينَ﴾ اور میرا ذكر خیر پچھلے لوگوں میں بھى باقى ركھ۔ (شعراء: ۸۴) ابن زید کہتے ہیں پس الله نے بعد میں آنے والے لوگوں میں انكا ذكر خیر ركھ چھوڑا اور ذكر سوء فرعون اور اس جیسوں كا مقدر بنادیا۔ (الطبرى: ۲۱؍۹۱)\nانسان كے ساتھ اللہ کے ارادہ خیر کی كوئى ایسی نشانى ذكر كیجئے جو آدمى كے مرنے كے بعد ظاہر ہوتى ہے.\nوَبَٰرَكۡنَا عَلَيۡهِ وَعَلَىٰٓ إِسۡحَٰقَۚ وَمِن ذُرِّيَّتِهِمَا مُحۡسِنٞ وَظَالِمٞ لِّنَفۡسِهِۦ مُبِينٞ ١١٣\nاس میں اس بات پر تنبیہ ہے كہ اچھے برے کا معیار نسل اور ذات نہیں ہے نیك برے كى كوكھ سے بھى جنم لے سكتاہےاور برا نیك كى نسل سے بھی پیدا ہوسكتاہے، نیز آنے والى نسل كے بگاڑ کو باپ دادا کی کمی اور خامی شمار نہیں کی جائے گی۔ فضل وبرترى كى بنیاد تو ذاتى صفات اور وه بھلائیاں ہیں جو آدمى حاصل كرتا اور سیكھتا ہے۔ البتہ باپ دادا کی شرافت بچوں کا کمال عزت اور اچھی صفتوں سے متصف ہونے کا باعث ہے۔ (ابن عاشور : ۲۳؍۱۶۲)\nاچھا یا برا ہونے كا معاملہ نسل پر مبنی نہیں ہے، اسے آیت كریمہ كى روشنى میں واضح كیجئے.\nوَبَٰرَكۡنَا عَلَيۡهِ وَعَلَىٰٓ إِسۡحَٰقَۚ وَمِن ذُرِّيَّتِهِمَا مُحۡسِنٞ وَظَالِمٞ لِّنَفۡسِهِۦ مُبِينٞ ١١٣\nجب الله تعالىٰ نے ذریت میں بركت وكثرت كا ذكر كیا تو فرمایا: ا ن میں كچھ نیك ہیں اور كچھ برے ہیں۔ اور برے كو نبوت كى طرف نسبت (یعنى نبى كا بیٹا ہونا) كوئى فائده نہیں دے سكى۔ لہذا یہود ونصارى اگرچہ اسحاق علیہ السلام كى اولاد ہیں اور عرب اسماعیل علیہ السلام كى اولاد سےہیں پھر بھى ان میں اچھے برے اور مومن وكافر كا فرق ضروری ہے ۔ (القرطبى: ۱۸؍۸۳)\nكیا آپ كیلئے آپ كےباپ كى صالحیت كافى ہے؟ اور كیا باپ کی خرابی آپ كے لئے مضر ہے؟\nwords\nأَسلَمَاوه دونوں حكم الٰهي كے سامنے سرنگوں هوئے.\nوَتَلَّهُ لِلجَبِينِاور اسے پيشاني كے بل زمين پر ليٹا ديا.\nوَفَدَينَاهُهم نے اس كا بدله ديا.\nبِذِبحٍايك مينڈھے سے.\nأَتَدعُونَ بَعلًاكيا تم بعل نامي بت كي پوجا كرتے هو."],[451,"§الصافات\ndeeds\nآپ یہ دعا پڑھئے: “اَللّٰهُمَّ اجْعَلْنِىْ مِنْ عِبَادِكَ الْمُخْلَصِيْنَ” اے اللہ! تو مجھے تیرے مخلص (چیدہ) بندوں میں شامل کر لے.\nآپ اپنے متعلقین میں سے كسى ایسے شخص كو یاد كیجئے جسے آپ نے دعوت دى اور اسكى ہدایت سے مایوس ہوچكے ، اپنى مایوسى پر الله سے معافى مانگئے كیونكہ یہ الله كى نافرمانى ہے.\nالله كى تسبیح بیان كیجئے ، ہو سكتا ہے اسى كے بدلے الله آپكى كوئى بلا ومصیبت ٹال دے.\nguid\nرسولوں كو جھٹلانے اور انہیں ایذاء پہنچانے والوں کے لئے جو شدید وعیدیں وارد ہیں ان پر نہایت سنجیدگى سے غور كیجئے.\nاچھى طرح سے جان لیجئے كہ صحیح سالم عقل مومن بندے كو نصیحت حاصل كرنے اور الله كى سنتوں میں غور وفكر پر آماده كرتى ہے.\nجان لیجئے كہ الله تعالىٰ سے متعلق بہتان سب سے بڑا بہتان ہے.\nrefl\nسَلَٰمٌ عَلَىٰٓ إِلۡ يَاسِينَ ١٣٠ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ١٣١ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ ١٣٢\nالیاس علیہ السلام كے واقعے میں اس بات كى خبر ہے کہ رسول كے ذمہ رسالت كى ادائیگى ہے ، اب اس سے یہ بات لازم نہیں آتى ہے كہ وه جھٹلانے والوں كى سزا یا انكى ہلاكت كا مشاہده بھى كرلے۔ نیز اس میں مشركین كے اس قول كى تردید بھی ہے جو كہتےتھے: اگر تم سچے ہو تو بتاؤ تمہارے وعدے کی گھڑی کا وقت کیا ہے؟ اللہ نے رسول کو حکم دیا کہ وہ یہ دعا كریں كہ اے میرے رب! اگر تو مجھے وه دكھائے جس كا وعده ان سے كیا جارہا ہے تو اے رب ! مجھے ان ظالموں كے گروه میں نہ كرنا، ہم جو كچھ وعدے انہیں دے رہے ہیں سب آپ كو دكھا دینے پر یقیناً قادر ہیں۔ (المومنون: ۹۳- ۹۵)\nداعی کی ذمہ داری صرف دعوت پہونچانا ہے، اپنے مخالف كی سزا كا انتظار كرنا نہیں۔ اسے آیت كریمہ كى روشنى میں بیان كیجئے.\nوَإِنَّكُمۡ لَتَمُرُّونَ عَلَيۡهِم مُّصۡبِحِينَ ١٣٧ وَبِٱلَّيۡلِۚ أَفَلَا تَعۡقِلُونَ ١٣٨\nتم سفر پہ جاتے ہوئےاور اس سے لوٹتے ہوئے ان تباه شده بستیوں سے صبح و شام گزرتے ہو، کیا پھر بھی نہیں سمجھتے ہو كیوں ان سے نصیحت حاصل نہیں كرتےہو؟ (البغوى: ۳؍۶۷۸)\nگزرے ہوئے لوگوں كے آثار اور کھنڈرات عبرت اورخوف كیلئے ہیں، تسلى خاطر اور تفریح طبع كیلئے نہیں ۔ اسے آیت كى روشنى میں واضح كیجئے.\nوَإِنَّ يُونُسَ لَمِنَ ٱلۡمُرۡسَلِينَ ١٣٩ إِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ١٤٠ فَسَاهَمَ فَكَانَ مِنَ ٱلۡمُدۡحَضِينَ ١٤١ فَٱلۡتَقَمَهُ ٱلۡحُوتُ وَهُوَ مُلِيمٞ ١٤٢ فَلَوۡلَآ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِينَ ١٤٣ لَلَبِثَ فِي بَطۡنِهِۦٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ ١٤٤\nآپ یہ جان لیں كہ یہاں یونس علیہ السلام كا ذكر نبى صلی اللہ علیہ وسلم كى تسلى كیلئے ہے كہ رسالت كى راه میں جن مشكلات كا سامنا آپ كر رہے ہیں انہیں آپ سے پہلے رسولوں نے جھیلا ہے ، ساتھ ساتھ یہاں مصائب سے دل برداشتہ نہ ہوکر ان پر صبر کرنے کے سلسلے میں نبى كریم صلی اللہ علیہ وسلم كا مقام ومرتبہ بھى نمایاں ہے اورتمام لوگوں کو یہ بتانا مقصود ہے كہ آپ صلی اللہ علیہ وسلم كو پیہم دعوت دین كا الله نے حكم دے ركھا تھا، اسلئے كہ مشركین یہ كہتے ہوئے رسول الله صلی اللہ علیہ وسلم پر عیب جوئى كرتے تھے كہ یہ تو ہمارے پیچھے پڑ گئے ہیں، ہر حال اور ہر گھڑى دعوت دیتے رہتےہیں۔ (ابن عاشور: ۲۳؍۱۷۸)\nیونس علیہ السلام كا قصہ یہاں كس مقصد كے تحت ذكر كیا گیا ہے؟\nوَإِنَّ يُونُسَ لَمِنَ ٱلۡمُرۡسَلِينَ ١٣٩ إِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ١٤٠\nالله تعالىٰ نے نہ تو یہ ذكر كیا كہ وه كس بات پر غصہ ہوئے تھے اور نہ ہى ان كا گناه كیونكہ اس میں ہمارا كوئى خاص فائده نہیں ہے، البتہ جو ہمارے لئے مفید تھى اسے ذکر کیا گیا وه یہ كہ یونس علیہ السلام نے خطا كى اور الله نے معزز رسول ہونے كے باوجود بھى انہیں سزادى۔ اور پھر نجات بھی دے دى، ملامت دور كى، نیز انكى درستگى كا سامان بھی فراہم كردیا۔ (السعدى: ۷۰۷)\nایك نبى سے ایك گناه سرزد ہوا جس پر الله نے انہیں سزادى، اس جانكارى سے آپ کو کیا سبق ملتا ہے؟\nإِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ١٤٠\nیعنى بھاگنے كا اراده كیا اور سمندر میں كشتى پر سوار ہوگئے،یہاں انكے بھاگنے كى تعبیر ایسے لفظ سے آئى ہے كہ جیسے كوئى غلام اپنے آقا سے بھاگتا ہے، كیونكہ وه تھے تو الله كے بندے اور غلام، اور الله كى اجازت كے بغیر ہى بھاگے تھے ۔ اور درحقیقت یہی (اباق) فرار ہونا ہے۔ (ابن عطیہ: ۴؍۴۸۵)\nلفظ (اباق)اپنے آقاسے غلام كے بھاگنے كیلئے استعمال ہوتاہے، تو یہاں یونس علیہ السلام كیلئے كیونكر استعمال كیا گیا حالانكہ وه تو آزاد تھے؟\nإِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ١٤٠\nیعنى وه كشتى كى جانب بھاگے(الفلك)یہاں واحد ہے، اور مشحون كامطلب بھرى ہوئى ، اور انكے بھاگنے كى وجہ اپنى قوم سے ناراضگى تھى، كیونكہ وه ایمان نہیں لارہےتھے۔(ابن جزى: ۲؍۲۴۱)\nالله كے نبى یونس علیہ السلام بھرى ہوئى كشتى كى طرف كیوں بھاگے تھے؟\nفَلَوۡلَآ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِينَ ١٤٣\nالله نے بتایا كہ یونس علیہ السلام تسبیح بیان كررہے تھے اور یہى تسبیح ان كے نجات كا سبب تھی۔ جب کوئی لغزش کھاتا ہے تو نیک کام ہی اسے تھامتا ہے۔ حسن بصری كہتےہیں كہ مچھلى كے پیٹ میں انہوں نے نماز نہیں پڑھی لیكن آسوده حالى میں نیك اعمال كئے تھے،اسی لئے انہیں نیک اعمال کے پاداش میں اللہ تعالیٰ نے انہیں مصیبت کی گھڑی میں یادکیا۔ (القرطبى: ۱۸؍۹۹)\nالله كے نبى یونس علیہ السلام كے نجات كا سبب كیا تھا؟\nwords\nالغَابِرِينَعذاب ميں باقي رهنے والے.\nأَبَقَاپنے رب كي اجازت كے بغير نكل كھڑا هوا.\nفَسَاهَمَپس قرعه اندازي كي ۔ (كشتي كے سواروں نے).\nالمُدحَضِينَقرعه كي وجه سے مغلوب.\nفَالتَقَمَهُپس اس كو نگل ليا.\nمُلِيمٌملامت كے كام كرنے والا.\nفَنَبَذنَاهُپس هم نے اسے نكال پھينكا(مچھلي كے پيٹ سے)."],[452,"§الصافات\ndeeds\nیہ دعا پڑھئے: “سُبْحَانَ اللّٰهِ وَبِحَمْدِهٖ، عَدَدَ خَلْقِهٖ، وَرِضَا نَفْسِهٖ، وَزِنَةَ عَرْشِهٖ، وَمِدَادَ كَلِمَاتِهٖ”میں اللہ تعالیٰ کی پاکیزگی بیان کرتا ہوں اس کی تعریفوں کے ساتھ اس کی مخلوق کی تعداد کے برابر اس کی ذات کی رضا کے برابر اس کے عرش کے وزن اور اس کے کلمات کی روشنائی کے برابر.\nنماز كى ادائیگى كے وقت صف میں بالكل سیدھے كھڑے رہئے.\nکوئی پیغام بھیج کر اس امت کی مدد کیجئے، تاکہ آپ اللہ کے ان بندوں میں شامل ہوجائیں جو اس کے دین کے حامی و ناصر ہیں.\nguid\nاس بات پر پختہ یقین ركھئے كہ بہر صورت الله كا دین غالب رہے گا.\nالله نے حكم دیا ہے كہ ہم جھٹلانے والوں سے كناره كش ہوجائیں.\nجب بھی بہتان تراشوں کی باتیں سنیں اللہ کی تسبیح و پاکی بیان کریں.\nrefl\nوَجَعَلُواْ بَيۡنَهُۥ وَبَيۡنَ ٱلۡجِنَّةِ نَسَبٗاۚ وَلَقَدۡ عَلِمَتِ ٱلۡجِنَّةُ إِنَّهُمۡ لَمُحۡضَرُونَ ١٥٨\nیعنى ان مشركین نے الله اور جنات كے بیچ رشتے دارى ٹھہرائى ہے، حالانكہ جنات کو بھی یہ معلوم ہے كہ انہیں الله كے روبرو جزا و سزا کے لئے فرمانبردار غلام بناکر پیش كئے جائیں گے، کیونکہ اگر ان كے اور الله كے درمیان كوئى قرابتدارى ہوتى تو انہیں اللہ کے سامنے حاضرہونا نہیں پڑتا۔\nجنات كے بارے میں یہ خبر دینے كا كیا مقصد ہے كہ وه حساب وكتاب كیلئے حاضر كئےجائیں گے؟\nفَإِنَّكُمۡ وَمَا تَعۡبُدُونَ ١٦١ مَآ أَنتُمۡ عَلَيۡهِ بِفَٰتِنِينَ ١٦٢ إِلَّا مَنۡ هُوَ صَالِ ٱلۡجَحِيمِ ١٦٣\nاس كا یہ مطلب ہے كہ شیطان بس اسى كو گمراه كرسكتا ہے جس كے بارے میں الله تعالیٰ نے لكھ دیا ہے كہ انہیں وه ہدایت نہیں پاسكتا ، اور اگر الله کے علم میں یہ ہوتا کہ وه ہدایت پائے گا تو الله ضرور اسكے اور شیطان كے درمیان حائل ہوجاتا ۔(القرطبى: ۱۸؍۱۱۲)\nكیا شیطان كیلئے یہ ممكن ہے كہ وه جب اور جیسے چاہےآپ کو گمراه كردے؟ آپ كو اس سے كیا فائده ملتا ہے؟\nوَمَا مِنَّآ إِلَّا لَهُۥ مَقَامٞ مَّعۡلُومٞ ١٦٤\nیعنى ہم میں سے ہر ایك فرشتے کی آسمانوں میں ایک جگہ مقرر ہے، جہاں وه الله كى عبادت كرتا ہے، ابن عباس رضی اللہ عنہما كا قول ہے : آسمانوں میں بالشت بھر جگہ بھى ایسى نہیں ہے جہاں كوئى فرشتہ نماز نہ پڑھ رہا ہو، یا تسبیح میں نہ مشغول ہو۔(البغوى: ۳؍۶۸۱)\nعبادت میں فرشتوں كا حال بیان كریں.\nوَإِنَّا لَنَحۡنُ ٱلصَّآفُّونَ ١٦٥\nیعنى عبادت میں صف بستہ كھڑے رہتےہیں، اسى لئے نماز میں مسلمانوں كو صفیں درست كرنےكا حكم دیا گیا ہے تاكہ فرشتوں كى اقتداء ہو ۔ واضح رہے كہ مسلمانوں كى طرح صف لگا كر كسى بھى مذہب میں كوئى نماز نہیں پڑھتا ہے۔ (ابن جزى: ۲؍۲۴۴)\nفرشتے مخلوقات میں جہاں سب سے زیاده طاقتور ہیں وہیں سب سے زیاده الله كیلئے تواضع بھى اپنانےوالے ہیں ۔ آیت كى روشنى میں اس کی وضاحت كیجئے.\nوَإِنَّا لَنَحۡنُ ٱلصَّآفُّونَ ١٦٥ وَإِنَّا لَنَحۡنُ ٱلۡمُسَبِّحُونَ ١٦٦\nابو نضره سے مروى ہے وہ كہتےہیں كہ جب نماز کے لئے اقامت کہی جاتی تو عمر رضی اللہ عنہ لوگوں كے روبرو ہوتےاور كہتے: لوگو! سیدھے كھڑے ہوجاؤ اللہ تعالیٰ تم سے فرشتوں کا طریقہ چاہتا ہے (وإنا لنحن الصافون * وإنا لنحن المسبحون)\" سیدھے کھڑے ہوجاؤ، اے فلاں! تم ذرا آگے آجاؤ، اور تم تھوڑا پیچھے ہوجاؤ، پھر جب سب برابر كھڑے ہوجاتے تب آگے بڑھتے اور الله اكبر كہتے۔ (الطبرى: ۲۱؍۱۲۸)\nمومنین اللہ کی تعظیم کے سلسلے میں ایك معاملے میں فرشتوں كے مشابہ ہیں ، اسے واضح كیجئے.\nسُبۡحَٰنَ رَبِّكَ رَبِّ ٱلۡعِزَّةِ عَمَّا يَصِفُونَ ١٨٠\nجب الله تعالىٰ نے اس سورت میں مشركین كے وه بہت سے برے اقوال ذكر كئے جس سے انہوں نے الله كو متصف كیا تو الله نے اپنے آپ کو ان تمام چیزوں سے پاک كرتےہوئے فرمایا: (سبحان ربك)آپ كا رب پاك ہے۔(السعدى: ۷۰۹)\nالله تعالىٰ نے سورت كے آخر میں اپنى پاكى كیوں بیان كى ہے؟\nوَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ١٨٢\nاور تمام تعریفات اللہ رب العالمین کے لئے ہیں یعنی اللہ تعالیٰ کہہ رہا ہے کہ تمام طرح کی تعریفات صرف اور صرف اللہ کے لئے ہے جو ثقلین جن اور انسان کا رب ہے، كیونكہ بندوں كى ہرنعمت اسى كى جانب سےہے، چنانچہ جس طرح بندوں كو ملى الله كى نعمتوں میں اس كا كوئى ساجھى دار نہیں ہے اسی طرح حمد وثنا بھی بلا شرکت خالص اسی کے لئے ہونی چاہئے ۔ (الطبرى: ۲۱؍۱۳۴)\nنعمتوں پر صرف اللہ کے لئے حمد کی تخصیص کیوں واجب ہے؟\nwords\nمَا لَكُم كَيفَ تَحكُمُونَبهت برا فيصله هے؛ جو فيصله تم كرتے هو.\nسُلطَانٌحجت.\nلَمُحضَرُونَضروروه عذاب ميں حاضر كئے جائيں گے.\nبِفَاتِنِينَكسي كو گمراه كرنے والے.\nصَالِ الجَحِيمِجو جهنم كي آگ ميں ڈالا جائے گا.\nالصَّآفُّونَصفيں باندھے الله كي عبادت كے ليے كھڑے.\nبِسَاحَتِهِمان كے صحن ميں (آخري كونے ميں )."]])